window.WORKBOOK = {"source": "択一・複数回答形式練習問題.xlsx", "questions": [{"id": 1, "sourceNote": "", "prompt": "正誤問題：ディメンションでビンを作成することができる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\nビンとは区間のことを言う。\nビンの編集画面でメジャーの値の範囲をどのように分割するか指定する。\nビンで編集ができるのはメジャー（または数値ディメンション）になるので、答えは誤り。\n参考：連続メジャーから連続のビンを作成する\nhttps://help.tableau.com/current/pro/desktop/ja-jp/calculations_bins.htm", "explanationImages": ["assets/image11.png"]}, {"id": 2, "sourceNote": "", "prompt": "正誤問題：ハイライトアクションは、ワークブック全体で無効にできる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n凡例表示をする場合、ワークブックやシートのハイライトアクションは、\nツールバーから無効または有効にすることができる\n参考：ハイライトアクション\nhttps://help.tableau.com/current/pro/desktop/ja-jp/actions_highlight.htm", "explanationImages": []}, {"id": 3, "sourceNote": "", "prompt": "正誤問題：同じビューで合計や平均のメジャーを複数回使用することができる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n同じビューでメジャーを複数回使用することは可能。\nたとえば、次の画像では同じビューで収益の合計と収益の平均の両方を使用している。", "explanationImages": ["assets/image12.png"]}, {"id": 4, "sourceNote": "", "prompt": "選択問題：定義上、Tableauは時間の経過に伴うメジャーを____として表示する", "choices": [{"key": "①", "text": "バブルチャート"}, {"key": "②", "text": "棒グラフ"}, {"key": "③", "text": "積み上げ棒グラフ"}, {"key": "④", "text": "折れ線グラフ"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④折れ線グラフ\n折れ線グラフは、ビュー内の個々のデータポイントを接続する。\nこれらは、一連の値を視覚化する簡単な方法を提供し、時間の経過に伴う傾向を\n確認したり、将来の値を予測したりする場合に役立つ。\n例：四半期の売上と利益を折れ線グラフで表示\n参考：バブルチャートの作成\nhttps://help.tableau.com/v10.5/pro/desktop/ja-jp/buildexamples_bubbles.html\n参考：折れ線グラフの作成\nhttps://help.tableau.com/v2018.2/pro/desktop/ja-jp/buildexamples_line.html", "explanationImages": ["assets/image13.png"]}, {"id": 5, "sourceNote": "", "prompt": "選択問題：単一のデータソース内の複数のテーブルに一度に接続するために使用するのは次のうちどれ？", "choices": [{"key": "①", "text": "データブレンド"}, {"key": "②", "text": "階層"}, {"key": "③", "text": "セット"}, {"key": "④", "text": "データ結合"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④データ結合\nTableauで分析するデータは、ビューの特定のフィールド(つまり列)で関連付けられた表の集まりで\n構成されている。\n結合は、共通のフィールド上の関連データを組み合わせる方法。\n結合を使用したデータの組み合わせの結果は、データの列を追加することによって\n通常は横方向に拡張された仮想テーブル。\n例：単一データソース内の複数テーブルをデータ結合した場合\n参考：データブレンド\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/multiple_connections.htm\n参考：階層\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/qs_hierarchies.htm\n参考：セットの作成\nhttps://help.tableau.com/current/pro/desktop/ja-jp/sortgroup_sets_create.htm\n参考：データの結合\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/joining_tables.htm", "explanationImages": ["assets/image14.png"]}, {"id": 6, "sourceNote": "", "prompt": "選択問題：Tableau Serverの実稼働での使用に推奨されるRAMの最小量はどれくらいか？", "choices": [{"key": "①", "text": "8GB"}, {"key": "②", "text": "16GB"}, {"key": "③", "text": "32GB"}, {"key": "④", "text": "65GB"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③32GB\nTableauServerの実稼働での使用に推奨されるRAMの最小量は32GB。\nインストールするPCのハードウェアの最小要件として覚えておく。", "explanationImages": []}, {"id": 7, "sourceNote": "", "prompt": "選択問題：ビンに変換されたデータを利用するのは次のどのグラフか？", "choices": [{"key": "①", "text": "ガントチャート"}, {"key": "②", "text": "ブレットグラフ"}, {"key": "③", "text": "ヒストグラム"}, {"key": "④", "text": "ツリーマップ"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nヒストグラム\n各グラフにどのような特徴があるか、グラフのイメージとセットで覚える。\n→\n各グラフ特徴\n参考：ガントチャートの作成\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/buildexamples_gantt.htm\n参考：ブレットグラフの作成\nhttps://help.tableau.com/current/pro/desktop/ja-jp/qs_bullet_graphs.htm\n参考：ヒストグラムの作成\nhttps://help.tableau.com/current/pro/desktop/ja-jp/buildexamples_histogram.htm\n参考：ツリーマップの作成\nhttps://help.tableau.com/current/pro/desktop/ja-jp/buildexamples_treemap.htm", "explanationImages": []}, {"id": 8, "sourceNote": "", "prompt": "正誤問題：傾向線は数値フィールドまたは日付フィールドでのみ使用できる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n傾向線をビジュアライゼーションに表示して、データのトレンドを強調することができる。\nビューに傾向線を追加するには、両方の軸に数値として解釈できるフィールドが含まれている必要がある。\nたとえば、列シェルフに文字列を含む製品カテゴリディメンションがあり、\n行シェルフに利益メジャーがあるビューにトレンドラインを追加することはできない。\nただし、売上と時間の両方を数値として解釈できるため、時間の経過に伴う売上のビューに\n傾向線を追加できる。\n例：年の経過に伴う売上の変化と傾向線\n参考：ビジュアライゼーションへの傾向線の追加\nhttps://help.tableau.com/v2018.3/pro/desktop/ja-jp/trendlines_add.htm", "explanationImages": ["assets/image15.png"]}, {"id": 9, "sourceNote": "", "prompt": "正誤問題：内部結合は両方のテーブルのすべての行が表示される", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\n問題の説明は外部結合のこと。\n→\n結合について", "explanationImages": []}, {"id": 10, "sourceNote": "", "prompt": "正誤問題：SUMは表計算ですか？", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\nSUMは集計関数でｓり、表計算ではない。\n表計算は、ビジュアライゼーションの値に適用する変換。\n表計算は、Tableauのローカルデータを計算する特殊な対応の計算フィールド。\nこれらは、現在ビジュアライゼーションにあるものに基づいて計算され、ビジュアライゼーションから\n除外されたメジャーまたはディメンションは考慮されない。\n最も一般的な表計算は以下。\n・\n累計\n・\n差\n…\n年によってどのように売上が増減しているかがわかる\n・\n差の割合\n…\n前年との売上の差を割合で確認できる\n・\n合計に対する割合\n・\nランク\n・\n百分位\n…\n100％を1位として％ランクを表示\n例：表計算を使用して、2017年各月の売上を基準に各年における各月の売上を割合で表示した場合\n参考：表計算のタイプ\nhttps://help.tableau.com/v2018.3/pro/desktop/ja-jp/calculations_tablecalculations_definebasic_runningtotal.htm", "explanationImages": ["assets/image16.png"]}, {"id": 11, "sourceNote": "", "prompt": "選択問題： デフォルトでは、ビューに配置されたメジャーは____によって集約される", "choices": [{"key": "①", "text": "カウント"}, {"key": "②", "text": "平均"}, {"key": "③", "text": "中央値"}, {"key": "④", "text": "合計"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n合計\nデフォルトでは、ビューに配置されたメジャーは合計によって集計される。\nこれは、すべての行のそのフィールドのデータが結合されることを意味する。\nメジャーは、平均、中央値、カウント、または個別のカウントとして集計することも可能。", "explanationImages": []}, {"id": 12, "sourceNote": "", "prompt": "選択問題：デフォルトでは、ビューに配置されたメジャーは____によって集約される", "choices": [{"key": "①", "text": "データクリーニング"}, {"key": "②", "text": "データの粒度"}, {"key": "③", "text": "データ接続"}, {"key": "④", "text": "データの詳細レベル"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nデータの粒度\nデータはさまざまな粒度レベルの粒度で生成及び分析される。\nたとえば、卒業データをみる場合、粒度は、データセットの行が一人の人物を表すのか、\n大学の卒業クラスを表すのかを表す。\n参考：Tableauでの詳細レベルの式の作成\n※LOD 表現は計算したい粒度のレベルをさらにコントロール可能\nhttps://help.tableau.com/current/pro/desktop/ja-jp/calculations_calculatedfields_lod.htm", "explanationImages": []}, {"id": 13, "sourceNote": "", "prompt": "選択問題：ブレット グラフの場合、少なくとも____メジャーが必要", "choices": [{"key": "①", "text": "3"}, {"key": "②", "text": "1"}, {"key": "③", "text": "2"}, {"key": "④", "text": "4"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n2\nブレットグラフとはあるデータを棒グラフの形で展開し、そこに比較したい基準データ(目標値など)を\n線の形でプロットしたもの。\n少ないスペースで2つのデータを比較することが可能。\n例；製品毎に売上と利益を比較したブレットグラフ", "explanationImages": ["assets/image17.png"]}, {"id": 14, "sourceNote": "", "prompt": "選択問題：全てのサポートファイル、データソース、アイコン、ログなどのデフォルトパスは_____にある", "choices": [{"key": "①", "text": "ドキュメント>Tableauファイル"}, {"key": "②", "text": "ドキュメント>Tableau"}, {"key": "③", "text": "ドキュメント>マイTableauリポジトリ"}, {"key": "④", "text": "ドキュメント>Tableauサポートファイル"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nドキュメント>マイTableauリポジトリ\nデフォルトでは、上記のすべてが[ドキュメント]>[マイTableauリポジトリ]に保存される。", "explanationImages": []}, {"id": 15, "sourceNote": "", "prompt": "選択問題：Tableauは、____個のディメンションと____個のメジャーを自動生成する", "choices": [{"key": "①", "text": "1,4"}, {"key": "②", "text": "2,2"}, {"key": "③", "text": "2,3"}, {"key": "④", "text": "1,2"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n1,4\n自動生成するものは以下の通り。\n1個のメジャー：メジャー名\n4個のディメンション：緯度、経度、レコード数、メジャー値\nTableau2020.2以降、データソース内のすべてのテーブルには、Name of Table(Count)の形式の\nCountフィールドがある。\nテーブルカウントフィールドは、自動的に生成され、計算されたフィールド。", "explanationImages": []}, {"id": 16, "sourceNote": "", "prompt": "選択問題：Tableauでは最大____個のテーブルを結合できる", "choices": [{"key": "①", "text": "16"}, {"key": "②", "text": "32"}, {"key": "③", "text": "64"}, {"key": "④", "text": "128"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n32\nTableauでは、最大32のテーブルを結合できる。", "explanationImages": []}, {"id": 17, "sourceNote": "", "prompt": "複数選択問題：Tableauでデータ抽出を使用する利点は次のうちどれ？", "choices": [{"key": "①", "text": "パフォーマンスの改善"}, {"key": "②", "text": "オフラインデータを使用できるようにするため"}, {"key": "③", "text": "常に最新のデータで作業するため"}, {"key": "④", "text": "作業スピードの改善"}], "answer": ["①", "②", "④"], "multiple": true, "images": [], "explanation": "①\nパフォーマンスの改善\n②\nオフラインデータを使用できるようにするため\n④\n作業スピードの改善\nデータ抽出は以下の理由で有利。\n(1) 大規模なデータセットをサポート\n数十億行のデータを含む抽出を作成できる。\n(2) 作成の高速化\n大規模なデータセットを操作している場合、抽出の作成と操作は、元のデータの操作よりも\n高速になる可能性がある。\n(3) パフォーマンスの向上に役立つ\n抽出データソースを使用するビューを操作する場合、通常、元のデータへの接続に基づいて\nビューを操作する場合よりもパフォーマンスが向上する。\n(4) 追加機能のサポート\n抽出を使用すると、Count Distinctを計算する機能など、元のデータでは使用できない、\nまたはサポートされていないTableau機能を利用できる。\n(5) データへのオフラインアクセスを提供する\n抽出を使用すると、元のデータが利用できない場合に、データをローカルに保存して操作できる。\nたとえば、旅行中。\n※ 「③常に最新のデータで作業するため」はライブ抽出の特徴\n接続方法の選択はデータソース画面右上の箇所から操作できる。", "explanationImages": ["assets/image18.png"]}, {"id": 18, "sourceNote": "", "prompt": "選択問題：最初にフィルターを適用し、上位N要素または下位N要素を表示する場合、次のフィルターのどれを使用するか？", "choices": [{"key": "①", "text": "データソースフィルター"}, {"key": "②", "text": "データ抽出フィルター"}, {"key": "③", "text": "コンテキストフィルター"}, {"key": "④", "text": "いずれでもない"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nコンテキストフィルター\nTableauには以下の複数のフィルターが存在する。\n(1) データ抽出フィルター\nTableau上でデータソースからデータ抽出を行い際に用いるフィルター。\n(2) データソースフィルター\nデータをシートに読み込む前に用いるフィルター。\n(3) コンテキストフィルター\n利用するデータを該当するフィルタに通るものだけに制限するためのフィルター。\nパフォーマンスの向上や上位・下位フィルターを設定する際に使用する。\n(4) ディメンションフィルター\n(5) メジャーフィルター\n(6) 表計算フィルター\n参考：フィルターと詳細レベルの式\nhttps://help.tableau.com/current/pro/desktop/ja-jp/calculations_calculatedfields_lod_filters.htm\n参考：コンテキストフィルターでビューのパフォーマンスを改善する\nhttps://help.tableau.com/current/pro/desktop/ja-jp/filtering_context.htm", "explanationImages": []}, {"id": 19, "sourceNote": "", "prompt": "選択問題：データソースをクリーンアップし、いくつかの計算フィールドを作成し、いくつかの列の名前を変更した。\nこれらの変更は、今後使用するために保存する必要がある。 次のうち、この要件を最もよく満たすのはどれ？", "choices": [{"key": "①", "text": ".twmファイルとして保存する"}, {"key": "②", "text": ".twbファイルとして保存する"}, {"key": "③", "text": ".tdsファイルとして保存する"}, {"key": "④", "text": ".twbxファイルとして保存する"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n.tdsファイルとして保存する\nTableauには以下のように様々なファイルが存在する。\n(1) ブックマーク(.tbm)\nTableauブックマークのファイルの拡張子は、.tbm。\nブックマークは、1つのワークシートを含み、作業内容を迅速に共有するための簡単な方法。\n(2) ワークブック(.twb)\nワークシート、ダッシュボード、ストーリーを含むファイル。\nファイル メニューから「名前を付けて保存」を選択した時のデフォルトの保存形式。\nデータソース(.tds)は含むが、データそのものは含まない純粋なレポート部分のみ*2保存する。\n次回ファイルを開いたタイミングでデータソース(.tds)の情報を元にデータに接続するため、\nデータ自体にアップデートがあればレポートの表示内容も更新される。\n(3) パッケージワークブック(.twbx)\nファイル メニューから「名前を付けて保存」を選択した時にファイルの種類をドロップダウン リスト\nで変更した場合の保存形式。\nワークブック(.twb)に加えて、ローカルのデータ(ExcelやAccessなど)と背景イメージ等を含むファイル。\nZip形式なので解凍してワークブック(.twb)とデータ部分に分けることができる。\n(4) 抽出ファイル(.tdeもしくは.hyper)\nTableauがローカルに保存するデータのスナップショット。\n必要なフィールドが少ない非常に大きなデータセットに適している。\nローカルデータソースではなく独自のデータベースエンジンにクエリを実行するため、\nパフォーマンスが最適化される。\n参考：Tableauファイル タイプとフォルダー\nhttps://help.tableau.com/current/pro/desktop/ja-jp/environ_filesandfolders.htm", "explanationImages": []}, {"id": 20, "sourceNote": "", "prompt": "正誤問題：複数の階層にフィールドを追加することができる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n例えば、データ型が日付であれば自動的に階層に分割される。\nまた、都道府県、市区町村のように各フィールドから階層を作成することも可能。\n参考：階層の作成\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/qs_hierarchies.htm", "explanationImages": ["assets/image19.png"]}, {"id": 21, "sourceNote": "", "prompt": "選択問題：1人あたりのGDPの計算方法として正しいものはどれ？", "choices": [{"key": "①", "text": "SUM([GDP]/[人口])"}, {"key": "②", "text": "SUM([人口]/[GDP])"}, {"key": "③", "text": "SUM([GDP]*[人口])"}, {"key": "④", "text": "SUM([GDP])/SUM([人口])"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nSUM([GDP])/SUM([人口])\nそれぞれの合計値で割る必要があるので、注意。\n参考；Tableauで使用する関数\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/functions.htm", "explanationImages": []}, {"id": 22, "sourceNote": "", "prompt": "選択問題：____を使用すると、Tableau Desktopでワークブックとビュー、ダッシュボード、\nおよびデータソースを作成し、このコンテンツを独自のサーバーに公開できる", "choices": [{"key": "①", "text": "Tableau Server"}, {"key": "②", "text": "Tableau Prep"}, {"key": "③", "text": "Tableau Public"}, {"key": "④", "text": "Tableau myサーバー"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nTableau Server\nTableau Serverを使用すると、Tableau Desktopでワークブックとビュー、ダッシュボード、\nおよびデータソースを作成し、このコンテンツを独自のサーバーに公開できる。\nさらに、Tableau Server管理者は、機密データの保護に役立つサーバーコンテンツにアクセスできる\nユーザーを制御できる。\n管理者は、プロジェクト、ワークブック、ビュー、およびデータソースにユーザー権限を設定できる。\n参考：Tableau Prep\n分析前に分析しやすいようデータを整理するためのツール\nhttps://help.tableau.com/current/prep/ja-jp/prep_about.htm\n参考：Tableau Public\n無償で利用できるTableau。\nワークブックの保存はオンラインのみなどDesktopに比べて機能に制限がある。\nTableauを使う練習にも利用可能。\nhttps://www.tableau.com/ja-jp/support/public", "explanationImages": []}, {"id": 23, "sourceNote": "", "prompt": "選択問題：次のうち、トレンドラインモデルではないものはどれか？", "choices": [{"key": "①", "text": "線形"}, {"key": "②", "text": "指数"}, {"key": "③", "text": "二項分布"}, {"key": "④", "text": "対数"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n二項分布\nTableauでは以下の傾向線を使用できる。\n(1) 線形\nデータの変化が一定の比率で増減している場合に適する。\n(2) 対数\nデータの変化が急速に大きく次第にゆるやかになる場合に適する。\n(3) 指数\nデータの変化がゆるやかで次第に大きくなる場合に適する。\n(4) 累乗\n線形と比べて傾きが徐々に変化していく場合に適する。\n(5) 多項\nデータの変化に山や谷が表れる場合に適する。\n※ 二項分布\n例えば、「コインを5回投げた時に表が2回でる確率」や「対戦ゲームで90％の確率で当たる技を\n10回中8回当てる確率」などを表した確率分布のこと。", "explanationImages": ["assets/image20.png"]}, {"id": 24, "sourceNote": "", "prompt": "正誤問題：ストーリー内でシートを使用することはできない。 シートはダッシュボード内で使用するか、\nダッシュボードをストーリー内で使用する必要がある。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\nTableauでは、ストーリー内でシートを使用することができる。\nストーリーはシートのコレクションでもあり、順番に並べられる。\nストーリー内の個々のシートは、ストーリーポイントと呼ばれる。", "explanationImages": ["assets/image21.png"]}, {"id": 25, "sourceNote": "", "prompt": "選択問題：ブレット グラフを使用する理由は次のうちどれか。", "choices": [{"key": "①", "text": "目標売上と売上を比較するため"}, {"key": "②", "text": "特定の期間における傾向を分析するため"}, {"key": "③", "text": "特定の売上に焦点を当てるため"}, {"key": "④", "text": "1年ごとの売上推移を確認するため"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n目標売上と売上を比較するため\n問13参照", "explanationImages": []}, {"id": 26, "sourceNote": "", "prompt": "正誤問題：データを分解して、ビュー内のすべてのマークを最も詳細なレベルで表示することができる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\nビューにメジャーを追加するたびに、デフォルトでそのメジャーに集計が適用される。\nこのデフォルトは、[分析]メニューの[メジャーの集計]設定によって制御される。\nビュー内のすべてのマークを最も詳細なレベルで表示する場合は、ビューを分解できる。\nデータを分解すると、Tableauはデータソースのすべての行のすべてのデータ値に個別のマークを表示する。\nビュー内のすべてのメジャーを分解するには：\n[分析]>[メジャーの集計]オプションをクリア。\nすでに選択されている場合は、[メジャーの集計]を一回クリックして選択を解除する。", "explanationImages": ["assets/image22.png"]}, {"id": 27, "sourceNote": "", "prompt": "選択問題：箱ひげ図の箱は何を表しているか。", "choices": [{"key": "①", "text": "データの最大値"}, {"key": "②", "text": "データの最小値"}, {"key": "③", "text": "四分位範囲"}, {"key": "④", "text": "データの中央値"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n四分位範囲\n箱の部分を四分位範囲という。\nデータを小さい方から順に並べたとき下から1/4の点、上から1/4の点を合わせて四分位数という。\n箱内の垂直線は中央値。ひげは箱の外側の2本の線で最大値と最小値を示している。", "explanationImages": ["assets/image23.gif"]}, {"id": 28, "sourceNote": "", "prompt": "複数選択問題：ダッシュボードに追加できるインタラクティブな要素は次のうちどれ？", "choices": [{"key": "①", "text": "URL"}, {"key": "②", "text": "フィルター"}, {"key": "③", "text": "ハイライトアクション"}, {"key": "④", "text": "ツールヒント"}], "answer": ["①", "②", "③"], "multiple": true, "images": [], "explanation": "①\nURL\n②\nフィルター\n③\nハイライトアクション\n以下図参照。\n※\nツールヒント\nグラフなどにカーソルを合わせると、データの詳細が表示される機能のこと。シートでのみ編集が可能。", "explanationImages": ["assets/image24.png"]}, {"id": 29, "sourceNote": "", "prompt": "選択問題： フィールドの背景が青色の場合、どういう意味を表すか？", "choices": [{"key": "①", "text": "連続"}, {"key": "②", "text": "不連続"}, {"key": "③", "text": "ディメンション"}, {"key": "④", "text": "メジャー"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n不連続\nメモ参照", "explanationImages": []}, {"id": 30, "sourceNote": "", "prompt": "選択問題：可変サイズのビンを作成するには、____を使用する", "choices": [{"key": "①", "text": "計算フィールド"}, {"key": "②", "text": "表計算"}, {"key": "③", "text": "セット"}, {"key": "④", "text": "グループ"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n計算フィールド\nビンとは区間のことを言う。\n問1のようにビンの編集画面でメジャーの値の範囲をどのように分割するか指定する方法の他に、\n(→問1)\n計算フィールドでビンを作成することもできる。\n例えば、年齢を表すメジャーがあるとする。\nメジャーを集計して平均年齢を計算する代わりに、メジャーをビン化して年齢グループ(0-5、6-10、11-15\nなど)を定義できる。\n次に各年齢層の人数を数えることができる。\n例：可変ビンサイズの計算フィールドを作成する。\nStep1\n[分析]>[計算フィールドの作成]を選択する。\nStep2\n[計算フィールド]ダイアログボックスで、次の手順を実行する。", "explanationImages": ["assets/image25.png"]}, {"id": 31, "sourceNote": "", "prompt": "正誤問題：アナリティクスペインからは参照線を追加することはできない", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\nビュー内の任意の連続軸に参照線を追加することができる。\n参照線を追加するには、参照線をアナリティクスペインからビューにドラックする。\n選択範囲は、アイテムのタイプと現在のビューによって異なる。\n単純なケースでは、ドロップターゲット領域には表、ペイン、セルという3つのオプションがある。", "explanationImages": ["assets/image26.png", "assets/image27.png"]}, {"id": 32, "sourceNote": "", "prompt": "正誤問題：左結合は左側のテーブルからすべての行を返し、右側のテーブルに一致する行を返す", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n左結合は左側のテーブル(table1)からすべてのレコードを返し、右側のテーブル(table2)から一致した\nレコードを返す。一致するものがない場合、結果は右側からNULLになる。\n参考：データの結合\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/joining_tables.htm", "explanationImages": ["assets/image28.jpeg"]}, {"id": 33, "sourceNote": "", "prompt": "選択問題：簡易表計算を使用するには、次のプログラミング言語のどれを知っておく必要があるか？", "choices": [{"key": "①", "text": "Python"}, {"key": "②", "text": "Java"}, {"key": "③", "text": "Javascript"}, {"key": "④", "text": "上記のいずれもない"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n上記のいずれもない\n簡易表計算は以下イメージのような計算表を簡単に作成できる機能で、プログラミング言語の知識は不要。\n参考：簡易表計算\nhttps://help.tableau.com/current/pro/desktop/ja-jp/calculations_tablecalculations_quick.htm", "explanationImages": ["assets/image29.png"]}, {"id": 34, "sourceNote": "", "prompt": "選択問題：マップを作成する場合、サイズ、形状、詳細、色に配置できるフィールドは次のうちどれ？", "choices": [{"key": "①", "text": "利益、州、レコード数、売上"}, {"key": "②", "text": "地域、国、収益、州"}, {"key": "③", "text": "経度、国、州、売上"}, {"key": "④", "text": "売上、州、国、利益"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n売上、州、国、利益\n売上高はメジャーであるため、サイズで簡単に表すことができる。\nドリルダウンして詳細レベルを変更するには、州が含まれるため、国が正しい選択。\n次に、円、正方形などのさまざまな形状でさまざまな状態を表すことができる。\n(以下イメージの場合、円で売上の大きさを表現)\n最後に利益は色で表現できる。\n例えば、利益が低い場合には赤、高い場合には緑といった表現ができる。", "explanationImages": ["assets/image30.png"]}, {"id": 35, "sourceNote": "", "prompt": "選択問題：ブレンドを使用する場合、プライマリデータソースとセカンダリデータソースの目盛りの色はそれぞれ何色か？", "choices": [{"key": "①", "text": "赤、青"}, {"key": "②", "text": "オレンジ、青"}, {"key": "③", "text": "青、赤"}, {"key": "④", "text": "青、オレンジ"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n青、オレンジ\nデータのブレンドとは、複数のソースからのデータを組み合わせる方法の一つ。\nブレンドを使用する場合、以下のようにプライマリデータソースは青のチェックマークで表示され、\nセカンダリデータソースはオレンジのチェックマークで表示される。", "explanationImages": ["assets/image31.png"]}, {"id": 36, "sourceNote": "", "prompt": "正誤問題：コンテキストフィルターは、データソースフィルターの後に実行される", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n問18参照", "explanationImages": []}, {"id": 37, "sourceNote": "", "prompt": "選択問題：このアイコンはTableauのどのデータ型を表しているか？　　T｜F", "choices": [{"key": "①", "text": "文字列"}, {"key": "②", "text": "True or False"}, {"key": "③", "text": "ブール値"}, {"key": "④", "text": "地理的値"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nブール値\nブール値では例えば国内・国外のように2種類のデータで区分される場合に適用するデータ型で\n文字列などよりも計算が速くなる。\n※\nTableauのデータ型とそのアイコンの一覧表", "explanationImages": ["assets/image32.png"]}, {"id": 38, "sourceNote": "", "prompt": "選択問題：相対日付フィルターの場合、デフォルトの設定は____。", "choices": [{"key": "①", "text": "現在の時刻"}, {"key": "②", "text": "現在の日付"}, {"key": "③", "text": "目標とする日付"}, {"key": "④", "text": "指定した日付"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n現在の日付\nビューを開いた時点を基準とする期間を表示するフィルターを作成することができる。\n例えば、以下のように現在の日付の前後3週間を常に表示することができる。\n参考；相対日付フィルターの作成\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/qs_relative_dates.htm", "explanationImages": ["assets/image33.png"]}, {"id": 39, "sourceNote": "", "prompt": "正誤問題：フィールドを連結するには、フィールドが同じデータ型である必要がある。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\nフィールドを連結するには、フィールドが同じデータ型である必要がある。\nフィールドとはテーブルに含まれる各データのことを指す。", "explanationImages": ["assets/image34.png"]}, {"id": 40, "sourceNote": "", "prompt": "複数選択問題：ダッシュボードのアクションを実行する方法は次のうちどれ？", "choices": [{"key": "①", "text": "ポイント"}, {"key": "②", "text": "クリック"}, {"key": "③", "text": "選択"}, {"key": "④", "text": "メニュー"}], "answer": ["①", "③", "④"], "multiple": true, "images": [], "explanation": "①\nポイント\n③\nクリック\n④\nメニュー\nダッシュボードのアクションを使用することで特定のカテゴリーのデータのみを抽出したりハイライトする\nことができる。\nアクションの作成方法に応じて、ポイント、選択、メニューのいずれかを使用してアクションを実行できる。\nなお、選択はクリックすることで機能するが、アクションの名称としてはあくまで選択になるので注意。\n※\nそれぞれの詳細は、メモ参照", "explanationImages": ["assets/image35.png"]}, {"id": 41, "sourceNote": "", "prompt": "選択問題：____は、Tableauがローカルに保存するデータのスナップショットで\n必要なフィールドが少なく、非常に大きなデータセットに適している。", "choices": [{"key": "①", "text": "パッケージワークブック(.twbx)"}, {"key": "②", "text": "ワークブック(.twb)"}, {"key": "③", "text": "抽出ファイル(.tde)"}, {"key": "④", "text": "データソース(.tds)"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n抽出ファイル(.tde)\n問19参照", "explanationImages": []}, {"id": 42, "sourceNote": "", "prompt": "選択問題：____を静的ツールとして使用して、TableauDesktopで作成された抽出データソースを含むパッケージ化された\nワークブックを開いて操作できる。", "choices": [{"key": "①", "text": "Tableau Reader"}, {"key": "②", "text": "Tableau Online"}, {"key": "③", "text": "Tableau Server"}, {"key": "④", "text": "Tableau Desktop"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nTableau Reader\nTableau OnlineやTableau Desktopは動的ツール、Tableau Readerは静的ツールと位置づけられている。\nTableau Readerは無料で利用できる。\nTableau ServerはTableau Desktopで作ったダッシュボードを共有するためのプラットフォーム。", "explanationImages": []}, {"id": 43, "sourceNote": "", "prompt": "複数選択問題：ビューなどに使用されるデータをエクスポートするオプションは次のうちどれ？", "choices": [{"key": "①", "text": "csvファイル"}, {"key": "②", "text": "PDFファイル"}, {"key": "③", "text": "jsonファイル"}, {"key": "④", "text": "Microsoft Accessデータベース"}], "answer": ["①", "④"], "multiple": true, "images": [], "explanation": "①\ncsvファイル\n④\nMicrosoft Accessデータベース\n元のデータのレコードのすべてまたは一部を含む、Tableauデータソースのデータをエクスポートできる。\nまたは、ビューの生成に使用されたデータの一部のみをエクスポートすることもできる。\nビュー内のデータをエクスポートする際には、[ワークシート]>[エクスポート]>[データ]を選択する。\nなお、csvファイルが対応しているのはMacのみ。\n※\njsonフォーマット…JavaScript用のデータ", "explanationImages": ["assets/image36.png"]}, {"id": 44, "sourceNote": "", "prompt": "選択問題：Tableauの日付は通常、____として扱われる。", "choices": [{"key": "①", "text": "ディメンション"}, {"key": "②", "text": "メジャー"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nディメンション\n日付と時刻はデータペインの[ディメンション]領域に自動的に配置され、日付または日時アイコンで識別\nされる。", "explanationImages": []}, {"id": 45, "sourceNote": "", "prompt": "選択問題：Tableauの____を使用して、データをクリーンアップ/整理できる。", "choices": [{"key": "①", "text": "データクリーナー"}, {"key": "②", "text": "データマネージャー"}, {"key": "③", "text": "データインタープリター"}, {"key": "④", "text": "データオーガナイザー"}], "answer": ["③"], "multiple": false, "images": ["assets/image1.png"], "explanation": "③\nデータインタープリター\nデータインタープリターにはTableauでのデータ解析を行いやすくするために、タイトル、注、フッター、\n空のセルなどの不必要なデータを除外し、必要なデータのみを抽出・整理する機能がある。\nデータソースの接続ペインからデータを追加し、表をキャンパスにドラッグするとデータインタープリター\nの使用チェックボックスが表示される。", "explanationImages": ["assets/image37.png"]}, {"id": 46, "sourceNote": "", "prompt": "選択問題：Tableauで次のメニュー(右欄外)は何と呼ばれているか？", "choices": [{"key": "①", "text": "データペイン"}, {"key": "②", "text": "アナリティクスペイン"}, {"key": "③", "text": "サマリーペイン"}, {"key": "④", "text": "分布ペイン"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nアナリティクスペイン\nデータペインの隣のタブがアナリティクスペイン。\nリファレンスラインを表示するなどに使用する基本的な機能。", "explanationImages": ["assets/image38.png"]}, {"id": 47, "sourceNote": "", "prompt": "選択問題：システムのWebブラウザを開くのではなく、ダッシュボードオブジェクトにURLアクションを展開して、\nダッシュボード内のWebページを開くことは可能か？", "choices": [{"key": "①", "text": "はい、プラグインでできます"}, {"key": "②", "text": "いいえ、現在できません"}, {"key": "③", "text": "はい、ウェブページのオブジェクトでできます"}, {"key": "④", "text": "はい、Tableau Publicでできます"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nはい、ウェブページのオブジェクトでできます\nダッシュボード内のWebからの情報をインタラクティブに表示するには、Webページオブジェクトで\nURLアクションを使用できる。\n例えば、国ごとの利益を表示するダッシュボードがあるとする。\nダッシュボードに利益データを表示するだけでなく、Webサイトから国に関する補足情報も表示できる。", "explanationImages": ["assets/image39.png", "assets/image40.png"]}, {"id": 48, "sourceNote": "", "prompt": "選択問題： Tableauで連続フィールドをどのように識別するか？", "choices": [{"key": "①", "text": "ビジュアル画面で表示される青のフィールド"}, {"key": "②", "text": "ビジュアル画面で表示される緑のフィールド"}, {"key": "③", "text": "データウィンドウに表示される＃の記号"}, {"key": "④", "text": "データウィンドウに表示されるABCの記号"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nビジュアル画面で表示される緑のフィールド\n青色は不連続、緑色は連続、＃は数値、ABCは文字列。", "explanationImages": []}, {"id": 49, "sourceNote": "", "prompt": "正誤問題：セットはメジャーで作成できる", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\nセットとは例えば東京、埼玉、神奈川とそれ以外の道府県といったように、2つのグループに分割する場合\nなどに使用する。\nセットを作成する際にはディメンションを使用する。(メジャーでは表示されない)", "explanationImages": ["assets/image41.png"]}, {"id": 50, "sourceNote": "", "prompt": "選択問題：グループ化されたフィールドに関連付けられているアイコンは____だ。", "choices": [{"key": "①", "text": "クリップ"}, {"key": "②", "text": "地球"}, {"key": "③", "text": "二つの輪"}, {"key": "④", "text": "＃"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nクリップ\n地球：地理的役割を持つ文字列\n二つの輪：セット\n＃：数値", "explanationImages": []}, {"id": 51, "sourceNote": "", "prompt": "選択問題：Tableauサポートケースは、次の有効な方法のどれで開くことができるか？", "choices": [{"key": "①", "text": "開発者のコミュニティフォーラム"}, {"key": "②", "text": "Salesforceのウェブサイト"}, {"key": "③", "text": "Tableauのサポートサイト"}, {"key": "④", "text": "Tableauの学習サイト"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nTableauのサポートサイト\nhttps://www.tableau.com/ja-jp/support/case", "explanationImages": []}, {"id": 52, "sourceNote": "", "prompt": "選択問題：次のグラフタイプのうち、常に降順で並べ替えられた棒が含まれているのはどれか？", "choices": [{"key": "①", "text": "パレート図"}, {"key": "②", "text": "円グラフ"}, {"key": "③", "text": "ガントチャート"}, {"key": "④", "text": "積み上げ棒グラフ"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nパレート図\n棒グラフと線グラフの両方を含むグラフのタイプ。\n例えば、ビジネスでは、収益の80％が利用可能な製品の20％から得られていることがよくあるが、\nこれをグラフで表す場合などに使用する。\n以下の例では左から6つまでの製品の売上で全体の60％を占めていることがわかる。", "explanationImages": ["assets/image42.png"]}, {"id": 53, "sourceNote": "", "prompt": "正誤問題：ディメンションの地理的役割は変更することができる。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n[データ]ペインで、フィールドの横にあるデータ型のアイコンをクリックし、[地理的役割]を選択してから、\nフィールドに割り当てる地理的役割を選択することで変更できる。", "explanationImages": ["assets/image43.png"]}, {"id": 54, "sourceNote": "", "prompt": "選択問題： [出荷日]-[注文日]の計算では、____が返される。", "choices": [{"key": "①", "text": "その間の注文数"}, {"key": "②", "text": "その間の日数"}, {"key": "③", "text": "その間のユニークな注文数"}, {"key": "④", "text": "その間の発送済み注文数"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nその間の日数\n名前が示すように、出荷日から注文日を引くと、これら2つの日付の間の日数が得られる。\nこれらはチャートでこの計算フィールドを使用でき、必要に応じてCOUNT、SUM、AVGなどを使用できる。", "explanationImages": []}, {"id": 55, "sourceNote": "", "prompt": "選択問題：次の図(右欄外)を説明するために使用される用語は何か？", "choices": [{"key": "①", "text": "パラメータ"}, {"key": "②", "text": "セット"}, {"key": "③", "text": "階層"}, {"key": "④", "text": "グループ"}], "answer": ["③"], "multiple": false, "images": ["assets/image2.png"], "explanation": "③\n階層\n階層は日付のように自動的に分割されるものもあれば、上記のようにRegion、State、Cityのように\n独自に作成することもできる。", "explanationImages": []}, {"id": 56, "sourceNote": "", "prompt": "正誤問題：左結合または内部結合は、結合基準が合致するたびに行を作成するため、行が重複する可能性がある。\nこれを回避する1つの方法は、代わりにデータブレンディングを使用することだ。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\nテーブルの詳細レベルが異なる場合は行の重複などが発生する可能性があり、分析を開始する前に\n結合されたデータソースを修正する必要がある。\nブレンドはデータを結合することはなく、適切なレベルで集約してビュー上に表示する。\n参考：データのブレンド\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/multiple_connections.htm", "explanationImages": []}, {"id": 57, "sourceNote": "", "prompt": "選択問題：____は、類似した特徴のマークを識別するTableauの手法。", "choices": [{"key": "①", "text": "クラスター"}, {"key": "②", "text": "グループ"}, {"key": "③", "text": "セット"}, {"key": "④", "text": "ユニオン"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nクラスター\nクラスター分析は、ビュー内のマークをクラスターに分割する。\nイメージは以下の通りで、アナリティクスペインのクラスターをビューにドラッグ＆ドロップすることで\n作成できる。\n※\nグループとセットの違い\n例えば、家具の売上を見る場合、グループは選択した特定の家具のみをグループとして表示できる。\n一方でセットはグループと同様のことのほかに売上合計が上位10位までを表示することなどができる。\n※\nユニオン\nユニオンは結合の一種ではないが、1つの表の行にあるデータを別の表に追加することによって\n2つ以上の表を組み合わせる別の方法。\nユニオンを実行する2つの表のフィールド数が同じであり、両方のフィールドで名前とデータ型が一致\nしていることが理想。", "explanationImages": ["assets/image44.png", "assets/image45.png", "assets/image46.png"]}, {"id": 58, "sourceNote": "", "prompt": "選択問題： Tableauで利益率を計算する正しい方法は次のうちどれ？", "choices": [{"key": "①", "text": "利益/売上"}, {"key": "②", "text": "売上/利益"}, {"key": "③", "text": "SUM(利益)/SUM(売上)"}, {"key": "④", "text": "SUM(売上)/SUM(利益)"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nSUM(利益)/SUM(売上)\n割合の計算などでは、各データにSUM関数で集計した上で計算する必要ありなので注意。", "explanationImages": []}, {"id": 59, "sourceNote": "", "prompt": "選択問題：次のうちどれが与えられた数の絶対値を返すか？", "choices": [{"key": "①", "text": "ABS"}, {"key": "②", "text": "ACOS"}, {"key": "③", "text": "ASIN"}, {"key": "④", "text": "ATAN"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nABS\n参考：数値関数\nhttps://help.tableau.com/current/pro/desktop/en-us/functions_functions_number.htm", "explanationImages": []}, {"id": 60, "sourceNote": "", "prompt": "複数選択問題：次の2つのフィールドのうち、Tableauで削除できないものはどれか？", "choices": [{"key": "①", "text": "メジャーの名前"}, {"key": "②", "text": "レコードの数"}, {"key": "③", "text": "メジャーの値"}, {"key": "④", "text": "計算フィールド"}], "answer": ["①", "③"], "multiple": true, "images": [], "explanation": "①\nメジャーの名前\n③\nメジャーの値\nメジャーの名前と値は、他の列のようにTableauで削除できない。自動生成される。\n一方で、計算フィールドとレコード数は削除できる。", "explanationImages": []}, {"id": 61, "sourceNote": "", "prompt": "選択問題：____には、視覚化の構築に必要な情報、およびデータソースのコピーが含まれている。", "choices": [{"key": "①", "text": "データソース(.tbs)"}, {"key": "②", "text": "パッケージワークブック(.twbx)"}, {"key": "③", "text": "ブックマーク(.tbm)"}, {"key": "④", "text": "ワークブック(.twb)"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nパッケージワークブック(.twbx)\nブックマーク(.tbm)\nTableauブックマークのファイルの拡張子は、.tbm。\nブックマークは、1つのワークシートを含み、作業内容を迅速に共有するための簡単な方法。\nデータソース(.tds)\nどこにあるどんなデータにどんな認証で接続し、どのテーブルを結合/ジョインしたとか、\nデータに対して行った変更(列名の変更/型の変換/別名/既定のプロパティ変更/計算フィールド作成等)\nの情報を持つファイル\nパッケージワークブック(.twbx)\nファイル メニューから「名前を付けて保存」を選択した時にファイルの種類をドロップダウン リスト\nで変更した場合の保存形式。\nワークブック(.twb)に加えて、ローカルのデータ(ExcelやAccessなど)と背景イメージ等を含むファイル。\nZip形式なので解凍してワークブック(.twb)とデータ部分に分けることができる。", "explanationImages": []}, {"id": 62, "sourceNote": "", "prompt": "選択問題：____は、視覚化したデータをWebに公開できるTableauのサービスだ。", "choices": [{"key": "①", "text": "Tableau Reader"}, {"key": "②", "text": "Tableau Desktop"}, {"key": "③", "text": "Tableau Server"}, {"key": "④", "text": "Tableau Public"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nTableau Public\nTableau Publicは、誰でもインタラクティブなデータ視覚化をWebに公開できる無料のサービス。\nTableau Publicに公開されたビジュアライゼーション(ビズ)は、Webページやブログに埋め込んだり、\nソーシャルメディアや電子メールで共有したり、他のユーザーがダウンロードできるようにしたりできる。", "explanationImages": []}, {"id": 63, "sourceNote": "", "prompt": "選択問題：次の関数は何を返すか？　LEFT(\"Tableau\", 3)", "choices": [{"key": "①", "text": "エラー"}, {"key": "②", "text": "Tab"}, {"key": "③", "text": "eau"}, {"key": "④", "text": "ble"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nTab\nLEFTはExcel関数と同じで、文字列の左から３文字を抽出する。", "explanationImages": []}, {"id": 64, "sourceNote": "", "prompt": "選択問題：行と列のカラムには____が含まれている。", "choices": [{"key": "①", "text": "ピル"}, {"key": "②", "text": "合計"}, {"key": "③", "text": "フィルター"}, {"key": "④", "text": "パラメーター"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nピル\n以下の例ではデータペインからフィールドをドラックして、CategoryとSUM(Sales)が列と行にそれぞれ\n配置されているが、これらをピルと呼ぶ。錠剤に形が似ていることに因んだ呼称のようだ。", "explanationImages": ["assets/image47.png"]}, {"id": 65, "sourceNote": "", "prompt": "選択問題：ディメンション内のメンバーの____を作成して、ビューで異なって表示されるようにすることができる。", "choices": [{"key": "①", "text": "パラメーター"}, {"key": "②", "text": "複製"}, {"key": "③", "text": "コピー"}, {"key": "④", "text": "別名"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n別名\nディメンション内のメンバーの別名を作成して、ビューで異なって表示されるようにすることができる。\nなお、別名は連続のディメンション、日付、またはメジャーには作成することはできない。", "explanationImages": []}, {"id": 66, "sourceNote": "", "prompt": "選択問題：あるテーブルから別のテーブルに値(行)を追加することで、データを____して2つ以上のテーブルを\n組み合わせることができる。", "choices": [{"key": "①", "text": "結合"}, {"key": "②", "text": "ブレンド"}, {"key": "③", "text": "連結"}, {"key": "④", "text": "ユニオン"}], "answer": ["④"], "multiple": false, "images": ["assets/image3.png"], "explanation": "④\nユニオン\nユニオンは結合の1種ではないが、1つの表の行にあるデータを別の表に追加することによって2つ以上の表を\n組み合わせる別の方法。\nユニオンを実行する2つの表のフィールド数が同じであり、両方のフィールドで名前とデータ型が一致して\nいることが理想。\n以下は3つのテーブルのユニオンのイメージ。", "explanationImages": ["assets/image48.png", "assets/image49.png"]}, {"id": 67, "sourceNote": "", "prompt": "選択問題：Tableauで次のビューは何と呼ばれているか？", "choices": [{"key": "①", "text": "アナリティクスペイン"}, {"key": "②", "text": "ウィンドウペイン"}, {"key": "③", "text": "データペイン"}, {"key": "④", "text": "ディメンションとメジャー"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nデータペイン\nワークスペースの左側に表示されているデータフィールドをデータペインという。", "explanationImages": []}, {"id": 68, "sourceNote": "", "prompt": "選択問題：複数のデバイスのダッシュボードを作成する場合、[デバイスプレビュー]セクションで使用できる\nデバイスオプションは次のうちどれか？", "choices": [{"key": "①", "text": "スマートフォン,モニター,ラップトップ,デフォルト"}, {"key": "②", "text": "スマートフォン,タブレット,ラップトップ,デスクトップ"}, {"key": "③", "text": "デフォルト,デスクトップ,スマートフォン,タブレット"}, {"key": "④", "text": "モニター,デフォルト,スマートフォン,タブレット"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nデフォルト,デスクトップ,スマートフォン,タブレット\nダッシュボードを作成するときに、[デバイスプレビュー]で次のオプションを使用できる。", "explanationImages": ["assets/image50.png"]}, {"id": 69, "sourceNote": "", "prompt": "選択問題：____は、オフラインで作業し、パフォーマンスを向上させる必要がある場合に、\n他のユーザーとデータを共有するために使用できるサブセットまたはデータセット全体のローカルコピーだ。", "choices": [{"key": "①", "text": ".twb"}, {"key": "②", "text": ".tbm"}, {"key": "③", "text": ".tde"}, {"key": "④", "text": ".twbx"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n.tde\n問題では抽出ファイルのことが説明されている。\nバージョン10.4までは、「抽出」を実行すると「.tde」というファイル形式で保存するようになっていたが\n10.5からは「.hyper」という形式で保存されるようになった。\n ブックマーク(.tbm)\nTableauブックマークのファイルの拡張子は、.tbm。\nブックマークは、1つのワークシートを含み、作業内容を迅速に共有するための簡単な方法。\nワークブック(.twb)\nワークシート、ダッシュボード、ストーリーを含むファイル。\nファイル メニューから「名前を付けて保存」を選択した時のデフォルトの保存形式。\nデータソース(.tds)は含むが、データそのものは含まない純粋なレポート部分のみ*2保存する。\n次回ファイルを開いたタイミングでデータソース(.tds)の情報を元にデータに接続するため、\nデータ自体にアップデートがあればレポートの表示内容も更新される。\nパッケージワークブック(.twbx)\nファイル メニューから「名前を付けて保存」を選択した時にファイルの種類をドロップダウン リスト\nで変更した場合の保存形式。\nワークブック(.twb)に加えて、ローカルのデータ(ExcelやAccessなど)と背景イメージ等を含むファイル。\nZip形式なので解凍してワークブック(.twb)とデータ部分に分けることができる。\n抽出ファイル(.tdeもしくは.hyper)\nTableauがローカルに保存するデータのスナップショット。\n必要なフィールドが少ない非常に大きなデータセットに適している。\nローカルデータソースではなく独自のデータベースエンジンにクエリを実行するため、\nパフォーマンスが最適化される。", "explanationImages": []}, {"id": 70, "sourceNote": "原本では4番目の選択肢も「③」と記載されています。識別のため「④」と表示しています。正答は原本の解説に準拠します。", "prompt": "複数選択問題：ワークシートの視覚化を画像としてコピーする有効な方法は次のうちどれか？", "choices": [{"key": "①", "text": "メインメニューのワークシートをクリックし、コピー>イメージ"}, {"key": "②", "text": "マークシェルフを使用し、コピー>イメージ"}, {"key": "③", "text": "ワークシートのビジュアル上で右クリックし、コピー>イメージ"}, {"key": "④", "text": "Ctrl + Vでコピーする"}], "answer": ["①", "③"], "multiple": true, "images": [], "explanation": "①\nメインメニューのワークシートをクリックし、コピー>イメージ\n③\nワークシートのビジュアル上で右クリックし、コピー>イメージ\n操作イメージは以下の通り。", "explanationImages": ["assets/image51.png", "assets/image52.png"]}, {"id": 71, "sourceNote": "", "prompt": "選択問題：ヒストグラムを作成したばかりで、ビンのサイズを動的に変更できるようにしたいと考えている。 \n次のうちどれを使用すると、要件を簡単に満たすことができますか？", "choices": [{"key": "①", "text": "セット"}, {"key": "②", "text": "グループ"}, {"key": "③", "text": "パラメータ"}, {"key": "④", "text": "計算"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nパラメータ\nパラメータでは、例えばSalesが＄500,000を超える場合はTrueを返し、それ以外の場合はFalseを返す\n計算フィールドを作成できる。\n式の「500,000」の定数値をパラメータに置き換えることができる。\n次に、パラメータコントロールを使用して、計算の閾値を動的に変更できる。", "explanationImages": ["assets/image53.png"]}, {"id": 72, "sourceNote": "", "prompt": "選択問題：通常の計算フィールドと、データブレンディング後に作成された計算フィールドの重要な違いは何か？", "choices": [{"key": "①", "text": "ブレンドされたフィールドは必ず最初に集計される"}, {"key": "②", "text": "違いはなく、計算フィールドはブレンドでは作られない"}, {"key": "③", "text": "ブレンドでできた計算フィールドは一度作成すると編集できない"}, {"key": "④", "text": "ブレンドでできた計算フィールドは2つ以上のフィールドで使えない"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nブレンドされたフィールドは必ず最初に集計される\nブレンドではデータが集計されてから組み合わされる。\nなお、結合の場合はデータが組み合わされてから集計される。\n参考：データのブレンド\nhttps://help.tableau.com/v2020.1/pro/desktop/ja-jp/multiple_connections.htm", "explanationImages": []}, {"id": 73, "sourceNote": "", "prompt": "選択問題：Tableau Desktopにデータセットをインポートすると、その中のすべてのフィールドが____に分割される。", "choices": [{"key": "①", "text": "行と列"}, {"key": "②", "text": "ディメンションとメジャー"}, {"key": "③", "text": "数とヘッダー"}, {"key": "④", "text": "ラベルと種類"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nディメンションとメジャー\n新しいデータソースに接続すると、Tableauは、フィールドに含まれるデータのタイプに応じて、\nデータソースの各フィールドをデータペインのディメンションまたはメジャーとして割り当てる。\nこれらのフィールドを使用して、データのビューを作成する。", "explanationImages": []}, {"id": 74, "sourceNote": "", "prompt": "複数選択問題：マークラベルを表示する方法は次のうちどれか？", "choices": [{"key": "①", "text": "マークカードのテキストラベルにメジャーをドラッグする"}, {"key": "②", "text": "メニューのアナリティクスをクリックし、マークラベルの表示を選択する"}, {"key": "③", "text": "メニューバーのデータをクリックし、マークラベルの表示を選択する"}, {"key": "④", "text": "ツールバーのマークラベルアイコンをクリックする"}], "answer": ["①", "②", "④"], "multiple": true, "images": [], "explanation": "①\nマークカードのテキストラベルにメジャーをドラッグする　\n②\nメニューのアナリティクスをクリックし、マークラベルの表示を選択する\n④\nツールバーのマークラベルアイコンをクリックする\nそれぞれの操作方法のイメージは次の通り。\n・\nツールバーのマークラベルアイコンをクリックする\n・\nマークカードのテキストラベルにメジャーをドラッグする　\n・\nメニューのアナリティクスをクリックし、マークラベルの表示を選択する", "explanationImages": ["assets/image54.png", "assets/image55.png", "assets/image56.png"]}, {"id": 75, "sourceNote": "", "prompt": "選択問題：____を色にドラッグすると、アイテムごとに異なる色が作成されるが、____を色にドラッグすると\nグラデーションが作成される。", "choices": [{"key": "①", "text": "連続と不連続"}, {"key": "②", "text": "地理的役割と不連続"}, {"key": "③", "text": "不連続と連続"}, {"key": "④", "text": "経度と緯度"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n不連続と連続\n不連続(青)はアイテムごとに異なる色が表示される。\n連続(緑)はグラデーションで色が表示される。", "explanationImages": ["assets/image57.png", "assets/image58.png", "assets/image59.png", "assets/image60.png"]}, {"id": 76, "sourceNote": "", "prompt": "選択問題：メタデータの管理オプションを使用すると、列のカスタム名を作成できる。ここで、____は列の元の名前だが\n____はTableauで作成したカスタム名だ。", "choices": [{"key": "①", "text": "Local Field,Grobal Field"}, {"key": "②", "text": "Local Name,Actual Name"}, {"key": "③", "text": "Remote Field Name,Field Name"}, {"key": "④", "text": "Column Name,Actual Name"}], "answer": ["③"], "multiple": false, "images": ["assets/image4.png"], "explanation": "③\nRemote Field Name,Field Name\nフィールド名が変更後の名前で、リモートフィールド名が元の名前。\nオリジナルデータが変更されることはなく、Tableau上でのみ変更される。", "explanationImages": []}, {"id": 77, "sourceNote": "", "prompt": "選択問題：ビュー内のすべてのマークを最も詳細なレベルで表示する場合は、ビューを____できる。", "choices": [{"key": "①", "text": "集計"}, {"key": "②", "text": "非集計"}, {"key": "③", "text": "分割"}, {"key": "④", "text": "ソート"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n非集計\nTableauではメジャーは自動で集計されるようになっているが、メジャーの集計のチェックを外すことで、\n非集計となり詳細なレベルでの表示が可能となる。", "explanationImages": ["assets/image61.png"]}, {"id": 78, "sourceNote": "", "prompt": "正誤問題：ビューのディメンションの数を増やすと、マークの数が増える。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n以下の例ではカテゴリーだけの場合は3個のマーク、サブカテゴリーの追加により17個のマークになった\nことがわかる。ビュー上の棒グラフの数3本から17本に増えている。", "explanationImages": ["assets/image62.png", "assets/image63.png"]}, {"id": 79, "sourceNote": "", "prompt": "選択問題： デフォルトのTableauリポジトリの場所をどのように変更できるか？", "choices": [{"key": "①", "text": "ウィンドウ>リポジトリの場所"}, {"key": "②", "text": "ファイル>リポジトリの場所から新しい場所を選択"}, {"key": "③", "text": "ヘルプ>リポジトリの場所を変更"}, {"key": "④", "text": "いつでも手動でリポジトリの場所を変更できる"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nファイル>リポジトリの場所から新しい場所を選択\n以下の通り。", "explanationImages": ["assets/image64.png"]}, {"id": 80, "sourceNote": "", "prompt": "正誤問題：複数のメジャーのグラフを1つのビューにまとめて表示することができる。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n以下の通り。売上と利益を1つのビューにまとめて表示している。", "explanationImages": ["assets/image13.png"]}, {"id": 81, "sourceNote": "", "prompt": "複数選択問題：総計をビューに追加する方法は次のうちどれか？", "choices": [{"key": "①", "text": "マークシェルフ"}, {"key": "②", "text": "アナリティクスペイン"}, {"key": "③", "text": "メニューバーの分析タブ"}, {"key": "④", "text": "データペイン"}], "answer": ["②", "③"], "multiple": true, "images": [], "explanation": "②\nアナリティクスペイン\n③\nメニューバーの分析タブ\n以下の通り。", "explanationImages": ["assets/image65.gif", "assets/image66.png"]}, {"id": 82, "sourceNote": "", "prompt": "選択問題：Tableauで使用できないクイックフィルターのタイプはどれか？", "choices": [{"key": "①", "text": "複数の値(リスト)"}, {"key": "②", "text": "正規表現の一致"}, {"key": "③", "text": "単一の値(スライダー)"}, {"key": "④", "text": "複数の値(カスタムリスト)"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n正規表現の一致\n以下の通り。", "explanationImages": ["assets/image67.png"]}, {"id": 83, "sourceNote": "", "prompt": "選択問題：____チャートは通常、時間の経過に伴う累積合計を表すために使用され、積み上げ線を表示する方法。", "choices": [{"key": "①", "text": "エリア"}, {"key": "②", "text": "ライン"}, {"key": "③", "text": "ブレット"}, {"key": "④", "text": "ガント"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nエリア\n以下の通り。", "explanationImages": ["assets/image68.png"]}, {"id": 84, "sourceNote": "", "prompt": "複数選択問題：TableauでURLアクションを作成するときに許可されるURLプレフィックスは次のうちどれ？", "choices": [{"key": "①", "text": "SMTP"}, {"key": "②", "text": "HTTP"}, {"key": "③", "text": "HTTPS"}, {"key": "④", "text": "FTP"}], "answer": ["②", "③", "④"], "multiple": true, "images": [], "explanation": "②\nHTTP\n③\nHTTPS\n④\nFTP\nURLアクションは、Tableauの外部にあるWebページ、ファイル、またはその他のWebベースのリソース\nを指すハイパーリンク。\nURLアクションを使用して、データに関する追加情報への電子メールまたはリンクを作成できる。\nデータに基づいてリンクをカスタマイズするために、フィールド値をパラメータとしてURLに自動的に\n入力できる。\n※\nFTP\n：\nFile Transfer Protocol\nコンピュータネットワーク上のクライアントとサーバ間でファイル転送を行うための通信\nプロトコルの一つ", "explanationImages": ["assets/image40.png"]}, {"id": 85, "sourceNote": "", "prompt": "選択問題：Tableauの「演算の優先順位」によると、最初に適用されるフィルターは次のうちどれ？", "choices": [{"key": "①", "text": "コンテキストフィルター"}, {"key": "②", "text": "データ抽出フィルター"}, {"key": "③", "text": "ディメンションフィルター"}, {"key": "④", "text": "メジャーフィルター"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nデータ抽出フィルター\nTableauには以下の複数のフィルターが存在する。\n(1) データ抽出フィルター\nTableau上でデータソースからデータ抽出を行い際に用いるフィルター。\n(2) データソースフィルター\nデータをシートに読み込む前に用いるフィルター。\n(3) コンテキストフィルター\n利用するデータを該当するフィルタに通るものだけに制限するためのフィルター。\nパフォーマンスの向上や上位・下位フィルターを設定する際に使用する。\n(4) ディメンションフィルター\n(5) メジャーフィルター\n(6) 表計算フィルター", "explanationImages": []}, {"id": 86, "sourceNote": "", "prompt": "選択問題：色に連続フィールドをドロップすると、Tableauは____の範囲の色で量的な凡例を表示する", "choices": [{"key": "①", "text": "不作成"}, {"key": "②", "text": "混在"}, {"key": "③", "text": "連続"}, {"key": "④", "text": "フェージング"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n連続\nマークカードの[色]に個別フィールドをドロップすると、Tableauはカテゴリパレットを表示し、フィールド\nの各値に色を割り当てる。\nColorに連続フィールドをドロップすると、Tableauは連続した色の範囲で量的な凡例を表示する。", "explanationImages": ["assets/image69.png"]}, {"id": 87, "sourceNote": "", "prompt": "選択問題：____アクションは、Tableauの外部にあるWebページ、ファイル、またはその他のWebベースの\nリソースを指すハイパーリンクだ。", "choices": [{"key": "①", "text": "URLに移動"}, {"key": "②", "text": "シート移動"}, {"key": "③", "text": "ウェブページに移動"}, {"key": "④", "text": "ハイパーリンクに移動"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nURLに移動\n③や④といったメニューは存在しないので注意。", "explanationImages": ["assets/image70.png"]}, {"id": 88, "sourceNote": "", "prompt": "正誤問題：マークカードの「色」に不連続フィールドをドロップした場合と、色に連続フィールドをドロップした場合と\nでは、異なるカラーパレットオプションが表示される。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n連続と不連続では以下の通り表示が異なる。\n・連続\n・\n不連続", "explanationImages": ["assets/image69.png", "assets/image71.png"]}, {"id": 89, "sourceNote": "", "prompt": "選択問題：____ソートの場合、データがどのように変更されても、値は常に、保持したソート順のままになる。", "choices": [{"key": "①", "text": "階層"}, {"key": "②", "text": "トポロジカル"}, {"key": "③", "text": "マニュアル"}, {"key": "④", "text": "ランダム"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nマニュアル\nマニュアルソートの場合、データがどのように変更されても、値は常に、保持したソート順のままになる。", "explanationImages": []}, {"id": 90, "sourceNote": "", "prompt": "複数選択問題：データをグループ化する有効な方法は次のうちどれ？", "choices": [{"key": "①", "text": "アナリティクスペイン"}, {"key": "②", "text": "マーク(バー)"}, {"key": "③", "text": "ディメンションシェルフ"}, {"key": "④", "text": "ラベル(名前)"}], "answer": ["②", "③", "④"], "multiple": true, "images": [], "explanation": "②\nマーク(バー)\n③\nディメンションシェルフ\n④\nラベル(名前)\n様々な方法でグループ化することができる。\n・\nマークの場合\nマーク(バー)を選択して電話、椅子、ストレージを選択してグループ化すると、次のようになる。\n別個のマーク(バー)のままだが、同じ色でグループ化されている。\n・\nラベル(名前)を選択してグループ化した場合\n別個のバーのままではなく、単一のバーに統合される。\n・\nディメンションシェルフから直接グループ化する場合", "explanationImages": ["assets/image72.png", "assets/image73.png", "assets/image74.png", "assets/image75.png", "assets/image76.png"]}, {"id": 91, "sourceNote": "", "prompt": "複数選択問題：Tableauでダッシュボードを作成するときに有効なオブジェクトは次のうちどれ？", "choices": [{"key": "①", "text": "拡張"}, {"key": "②", "text": "ビデオ"}, {"key": "③", "text": "テキスト"}, {"key": "④", "text": "Webページ"}, {"key": "⑤", "text": "イメージ"}], "answer": ["①", "③", "④", "⑤"], "multiple": true, "images": [], "explanation": "①\n拡張\n③\nテキスト\n④\nWebページ\n⑤\nイメージ\nダッシュボードで有効なオブジェクトは以下の通り。ビデオはない。", "explanationImages": ["assets/image77.png"]}, {"id": 92, "sourceNote": "", "prompt": "選択問題：_____は、データソースの構成方法をシートごとに変更する必要がある場合、および関係や\n結合を許可しないデータベースを結合する場合に役立つ", "choices": [{"key": "①", "text": "ユニオン"}, {"key": "②", "text": "データブレンディング"}, {"key": "③", "text": "データ結合"}, {"key": "④", "text": "データ分離"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nデータブレンディング\nデータブレンディングはシートごとに実行され、2番目のデータソースのフィールドがビューで使用される\nときに確率される。\n少なくとも2つのデータソースにすでに接続されているブックにブレンドを作成するには、1つの\nデータソースからシートにフィールドを移動する。これが、プライマリーデータソースになる。\n他のデータソースに切り替えて、同じシートのフィールドを使用する。これがセカンダリデータソース。\nオレンジ色のリンクアイコンがデータペインに表示され、データソースのブレンドに使用されている\nフィールドを示す。", "explanationImages": []}, {"id": 93, "sourceNote": "", "prompt": "選択問題：ディメンション内のメンバーの____を作成して、メンバーのラベルがビューで異なって表示されるように\nすることができる。", "choices": [{"key": "①", "text": "別名の編集"}, {"key": "②", "text": "複製"}, {"key": "③", "text": "コピー"}, {"key": "④", "text": "名前の変更"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n別名の編集\nディメンション内のメンバーのエイリアス(代替名)を作成して、それらのラベルがビューで異なって\n表示されるようにすることができる。\nエイリアスは、不連続のディメンションのメンバーに対してのみ作成できる。\n連続のディメンション、日付、メジャーに対して作成することはできない。", "explanationImages": ["assets/image78.png", "assets/image79.png"]}, {"id": 94, "sourceNote": "", "prompt": "選択問題：Tableau 2020.1で導入された新機能ではないものは次のうちどれ？", "choices": [{"key": "①", "text": "セットコントロール"}, {"key": "②", "text": "Vizアニメーション"}, {"key": "③", "text": "動的パラメータ"}, {"key": "④", "text": "バッファー計算"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nセットコントロール\nセットコントロールは2020.2バージョンで導入された新機能。\n(1) Vizアニメーション\nVizアニメーションは、変化するデータを確認して理解するのに役立つ。\n並べ替え、フィルタリング、フィールドの追加、およびその他のアクションにより、視覚化が\nスムーズにアニメーション化されるようになった。\n↑画像リンク\n(2)動的パラメータ\n基になるデータが変更されるたびに、パラメータを使用してワークブックを再作成されることがなくなる。\nパラメータを一度設定すると、誰かがワークブックを開くたびに、Tableauはパラメータの値のリストを\n自動的に更新する。\n(3)バッファー計算\nバッファ計算により、ポイント位置の周囲の距離を視覚化できる。\nTableauに3つのパラメータ(場所、距離、測定単位)を与えると、バッファーまたは境界が即座に作成\nされる。\n複雑な空間に関する質問への回答がこれまでになく簡単になった。\n提案されたトランジットサイトから200メートル以内にある物件や、店舗から１マイル以内にある\n競合他社の店舗の数などを視覚化できる。", "explanationImages": ["assets/image80.gif", "assets/image81.png"]}, {"id": 95, "sourceNote": "", "prompt": "選択問題： ____と____の値を含むディメンションは連続にはできない。", "choices": [{"key": "①", "text": "日付"}, {"key": "②", "text": "日付と時間"}, {"key": "③", "text": "ブール値"}, {"key": "④", "text": "文字列"}], "answer": ["③", "④"], "multiple": true, "images": [], "explanation": "③\nブール値\n④\n文字列\nそれぞれの説明", "explanationImages": []}, {"id": 96, "sourceNote": "", "prompt": "選択問題：Tableauで値を集計するレベルを確認する方法は次のどれ？", "choices": [{"key": "①", "text": "集計は常にTableauの特別な式によって行われる"}, {"key": "②", "text": "数値はデータ単位で集計される"}, {"key": "③", "text": "Tableauでは数値の集計は行わないので、自分で行う必要がある"}, {"key": "④", "text": "数値はワークシート単位で集計される"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n数値はワークシート単位で集計される\nTableauでは、メジャーまたはディメンションを集約できるが、メジャーを集約するのが一般的。\nビューにメジャーを追加するたびに、デフォルトでそのメジャーに集計が適用される。\n適用される集計のタイプは、ビューのコンテキストによって異なる。\nビューにメジャーを追加すると、Tableauはその値を自動的に集計する。\n合計、平均、および中央値は一般的な集計。\n現在の集計は、ビューにメジャーの名前の一部として表示される。\n例えば、SalesはSUM(Sales)になる。\nすべてのメジャーには、データソースに接続ずるときにTableauによって設定されるデフォルトの集計がある。\nビューのメジャーの集計はコンテキストメニューから変更できる。", "explanationImages": ["assets/image82.png"]}, {"id": 97, "sourceNote": "", "prompt": "選択問題：データソースページからSheet1をクリックすると、上記のようにTableauDesktopワークスペースが開く。\nあなたがここでする主なことは何か？", "choices": [{"key": "①", "text": "データを分析するためのビジュアルを作る"}, {"key": "②", "text": "データをプレビューする"}, {"key": "③", "text": "データをきれいにする"}, {"key": "④", "text": "フィールド名とデータの型を変更する"}], "answer": ["①"], "multiple": false, "images": ["assets/image5.png"], "explanation": "①\nデータを分析するためのビジュアルを作る\n各機能のおさらい。\nA\nブック名。\nワークブックにはシートが含まれている。\nシートは、ワークブック、ダッシュボード、またはストーリーにすることができる。\n詳細はワークブックとシートを参照。\nB\nカードとシェルフ。\nフィールドをワークスペースのカードとシェルフにドラックして、ビューにデータを追加する。\nC\nツールバー。\nツールバーを使用して、コマンド、分析及びナビゲーションツールにアクセスする。\nD\nビュー。\nこれは、ビジュアライゼーション(「Viz」とも呼ばれる)を作成するワークスペース内のキャンパス。\nE\nこのアイコンをクリックして、データに接続できるスタートページに移動する。\nF\nサイドバー。\nワークシートでは、サイドバー領域にデータペインと分析ペインが含まれる。\nG\nこのタブをクリックして、[データソース]ページに移動し、データを表示する。\n詳細はデータソースページを参照。\nH\nステータスバー。\n現在のビューに関する情報を表示する。\nI\nシートタブ。\nタブは、ワークブックの各シートを表す。\nこれには、ワークシート、ダッシュボード、及びストーリーを含められる。", "explanationImages": ["assets/image83.png"]}, {"id": 98, "sourceNote": "", "prompt": "選択問題：_____は、テーブルに値（行）を追加するための方法。 両方のテーブルの列が同じ場合は、この方法を使用\nできる。 同じ列でデータの行を追加することにより垂直方向に拡張される仮想テーブル。", "choices": [{"key": "①", "text": "ブレンディング"}, {"key": "②", "text": "組み合わせ"}, {"key": "③", "text": "結合"}, {"key": "④", "text": "ユニオン"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nユニオン\nユニオンは１つの表の行にあるデータを別の表に追加することによって２つ以上の表を組み合わせる\n別の方法。\nユニオンを実行する２つの表のフィールド数が同じであり、両方のフィールドで名前とデータ型が\n一致していることが理想。", "explanationImages": []}, {"id": 99, "sourceNote": "", "prompt": "選択問題：_____は、サポートするローカルファイルデータと背景画像とともにワークブックを含む単一のzipファイル。 \nこの形式は、元のデータにアクセスできない他のユーザーと共有するために作品をパッケージ化するための最良の方法。", "choices": [{"key": "①", "text": ".tdeファイル"}, {"key": "②", "text": ".tbmファイル"}, {"key": "③", "text": ".twbファイル"}, {"key": "④", "text": ".twbxファイル"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n.twbxファイル\nTableauパッケージワークブックのファイル拡張子は.twbx。\nパッケージ化されたワークブックは、サポートするローカルファイルデータと背景画像とともに\nワークブックを含む単一のzipファイル。\nこの形式は、元のデータにアクセスできない他のユーザーと共有するために作品をパッケージ化する\nための最良の方法。", "explanationImages": []}, {"id": 100, "sourceNote": "", "prompt": "選択問題： [データの表示]ウィンドウには、デフォルトで、最大____行までの可能な限り多くのデータが表示される。", "choices": [{"key": "①", "text": "5000"}, {"key": "②", "text": "10000"}, {"key": "③", "text": "15000"}, {"key": "④", "text": "20000"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n10000(行)\n[データの表示]ウィンドウには、デフォルトで可能な限り多くのデータが最大10000行表示される。\nただし、必要に応じて、これを増やすことができる。", "explanationImages": ["assets/image84.png", "assets/image85.png"]}, {"id": 101, "sourceNote": "", "prompt": "選択問題： 一般的なベストプラクティスとして、円グラフはいくつのカテゴリを効果的に表示できるか？", "choices": [{"key": "①", "text": "3-5"}, {"key": "②", "text": "2-8"}, {"key": "③", "text": "3-7"}, {"key": "④", "text": "2-5"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n2-5(個)\n一般的なベストプラクティスとして、円グラフのは2～５個のカテゴリが含まれている必要がある。\nそれ以上のものは、目で区別するのは簡単ではない。", "explanationImages": []}, {"id": 102, "sourceNote": "", "prompt": "選択問題：ビジュアライゼーションの形状、色、テキストを編集するために使用するのは次のうちどれ？", "choices": [{"key": "①", "text": "フィルター"}, {"key": "②", "text": "マークカード"}, {"key": "③", "text": "データペイン"}, {"key": "④", "text": "アナリティクスペイン"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nマークカード\nマークカードを使用すると、形状、テキスト、色を編集できるたけでなく、ツールチップや視覚化の\n詳細レベルを変更することもできる。\nワークシート上における各機能の該当箇所は以下のイメージ通り。", "explanationImages": ["assets/image86.png"]}, {"id": 103, "sourceNote": "", "prompt": "複数選択問題：ワークシートをTableauで画像としてエクスポートする場合、次のファイル形式のどれを使用できるか？", "choices": [{"key": "①", "text": "JPEGファイル"}, {"key": "②", "text": "TIFFファイル"}, {"key": "③", "text": "BMPファイル"}, {"key": "④", "text": "PNGファイル"}], "answer": ["①", "③", "④"], "multiple": true, "images": [], "explanation": "①\nJPEGファイル\n③\nBMPファイル\n④\nPNGファイル\n上記に加えて拡張メタファイルの保存も可能。\n手順は以下の通り。", "explanationImages": ["assets/image87.png", "assets/image88.png", "assets/image89.png"]}, {"id": 104, "sourceNote": "", "prompt": "選択問題：TableauをCSVデータソースに接続するには、どのタイプの接続を使用する必要があるか？", "choices": [{"key": "①", "text": "JSON"}, {"key": "②", "text": "Excel"}, {"key": "③", "text": "Spatical"}, {"key": "④", "text": "テキスト"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nテキスト\nTableauはCSVファイルをTEXTファイルとして認識する。", "explanationImages": ["assets/image90.png", "assets/image91.png"]}, {"id": 105, "sourceNote": "", "prompt": "選択問題：Tableauの数値を通貨としてフォーマットするにはどうすればよいか？", "choices": [{"key": "①", "text": "ビュー上のメジャーか軸を右クリックし書式設定を選択する。それから数値のドロップダウンメニューをクリックする。"}, {"key": "②", "text": "ビュー上で使用されているデータソースを右クリックし書式設定を選択する。それから数値のドロップダウンメニュー\nをクリックする。"}, {"key": "③", "text": "シート名を右クリックし書式設定を選択する。それから数値のドロップダウンメニューをクリックする。"}, {"key": "④", "text": "ビュー上のディメンションを右クリックし書式設定を選択する。それから数値のドロップダウンメニューをクリックする。"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nビュー上のメジャーか軸を右クリックし書式設定を選択する。それから数値のドロップダウン\nメニューをクリックする。\n書式設定の変更手順は以下の通り。", "explanationImages": ["assets/image92.png", "assets/image93.png"]}, {"id": 106, "sourceNote": "", "prompt": "正誤問題：定性的データと定量的データに対してさまざまなフィルタリングオプションを利用できる。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "〇\nディメンションもメジャーもフィルターを行うことができる。\nなお、ディメンションとメジャーでフィルターのオプションが異なる。\nディメンションをデータペインからTableau Desktopの[フィルター]シェルフにドラッグすると、\n次の[フィルター]ダイアログボックスが表示される。\nメジャーをデータペインからTableau Desktopの[フィルター]シェルフにドラッグすると、次の\nダイアログボックスが表示される。", "explanationImages": ["assets/image94.png", "assets/image95.png"]}, {"id": 107, "sourceNote": "", "prompt": "選択問題：____はヘッダーのみを作成する。 ____は、ヘッダーと軸の両方を作成する。", "choices": [{"key": "①", "text": "データ、文字列"}, {"key": "②", "text": "メジャー、ディメンション"}, {"key": "③", "text": "ディメンション、メジャー"}, {"key": "④", "text": "グループ、セット"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nディメンション、メジャー\n(1)各セグメントのSUM(数量)を示す棒グラフをプロットしてみる。\n(2)セグメントを右クリックする。\n軸を編集するオプションはなく、ヘッダーのみであることに注意。\nこれは、連続した値のみが軸を作れるから。\n(3)同様に、数量をクリックする。\nこちらはメジャーなので、軸の編集が可能となっている。", "explanationImages": ["assets/image96.png", "assets/image97.png", "assets/image98.png"]}, {"id": 108, "sourceNote": "", "prompt": "選択問題：ツリーマップでは、サイズは____の最大の長方形と____の最小の長方形で始まる。", "choices": [{"key": "①", "text": "右上、左下"}, {"key": "②", "text": "左上、右下"}, {"key": "③", "text": "右上、右下"}, {"key": "④", "text": "左上、左下"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n左上、右下\nツリーマップのサイズは、左上の最大値から右下の最小値になる。", "explanationImages": ["assets/image99.png"]}, {"id": 109, "sourceNote": "", "prompt": "選択問題：次のフィルタが表示されている場合は、____を使用している。", "choices": [{"key": "①", "text": "データファンクション"}, {"key": "②", "text": "不連続"}, {"key": "③", "text": "連続"}, {"key": "④", "text": "グループ化されたデータ"}], "answer": ["③"], "multiple": false, "images": ["assets/image6.png"], "explanation": "③\n連続\nTableauの日付は、不連続(青)か連続(緑)かよって動作が異なる。\nこれは、軸の表示/動作、及び折れ線グラフなどの視覚化の表示方法に影響する。\n違いは不連続はビュー上の個別のカテゴリのように動作するが、連続は連続した数値のように動作する。", "explanationImages": []}, {"id": 110, "sourceNote": "", "prompt": "正誤問題:Tableauのストーリーポイントにダッシュボードとワークシートの両方を同時に追加することができる.", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["×"], "multiple": false, "images": [], "explanation": "×\n各ストーリーにそれぞれを追加することはできるが、両方を同時に追加することはできない。\n参考：ストーリーの作成\nhttps://help.tableau.com/v2018.1/pro/desktop/ja-jp/story_create.html", "explanationImages": []}, {"id": 111, "sourceNote": "", "prompt": "選択問題： データペインからディメンションに地理的役割を手動で割り当てるにはどうすればよいか？", "choices": [{"key": "①", "text": "右クリック>地理的役割>適用したい地理的役割を選択"}, {"key": "②", "text": "右クリック>デフォルトのプロパティ>地理的役割を適用"}, {"key": "③", "text": "マイドキュメントのコンフィグファイルを編集>"}, {"key": "④", "text": "早期解決のためにデータソースを手動で編集する"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n右クリック>地理的役割>適用したい地理的役割を選択\nデータペインから、ディメンションを右クリックし、地理的な役割を選択してから、次のように\n適切な役割を選択する。", "explanationImages": ["assets/image100.png"]}, {"id": 112, "sourceNote": "", "prompt": "複数選択問題：tdsファイルにはどのような情報が保存されているか？", "choices": [{"key": "①", "text": "ビジュアル"}, {"key": "②", "text": "メタデータ"}, {"key": "③", "text": "抽出データ"}, {"key": "④", "text": "計算フィールド"}, {"key": "⑤", "text": "データ接続情報"}], "answer": ["②", "④", "⑤"], "multiple": true, "images": [], "explanation": "②\nメタデータ\n④\n計算フィールド\n⑤\nデータ接続情報\nデータソース(.tds)とはどこにあるどんなデータにどんな認証で接続し、どのテーブルを結合/ジョイン\nしたとか、データに対して行った変更(列名の変更/型の変換/別名/既定のプロパティの変更/計算\nフィールドの作成など)の情報を持つファイルのことを指す。", "explanationImages": []}, {"id": 113, "sourceNote": "", "prompt": "複数選択問題：次の目的でコンテキストフィルターを作成できる。", "choices": [{"key": "①", "text": "パフォーマンスの改善"}, {"key": "②", "text": "単独N位または上位Nのフィルター"}, {"key": "③", "text": "データソースフィルターの置き換え"}, {"key": "④", "text": "独立したフィルターの作成"}], "answer": ["①", "②"], "multiple": true, "images": [], "explanation": "①\nパフォーマンスの改善\n②\n単独N位又は上位N位のフィルター\nコンテキストフィルターとは、利用するデータを該当するフィルターに通るものだけに制限するための\nフィルターで、パフォーマンスの向上や上位・下位Nフィルターを設定する際に使用する。\n参考：コンテキスト フィルターでビューのパフォーマンスを改善する\nhttps://help.tableau.com/current/pro/desktop/ja-jp/filtering_context.htm", "explanationImages": []}, {"id": 114, "sourceNote": "", "prompt": "選択問題：Tableauでアニメーションを使用する場合、アニメーションのデフォルトの期間は次のうちどれ？", "choices": [{"key": "①", "text": "0.5秒"}, {"key": "②", "text": "0.2秒"}, {"key": "③", "text": "0.3秒"}, {"key": "④", "text": "0.4秒"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n0.3秒\n視覚化をアニメーション化して、データの変化するパターンをより適切に強調し、スパイクと外れ値\nを明らかにし、データポイントがどのようにクラスター化及び分離するかを確認する。\n例えば、デフォルトの同時アニメーションはより高速で、より単純なチャートやダッシュボードで\n値の変化を表示するときにうまく機能する。\nワークブックで視覚化をアニメーション化する手順は以下の通り。\n(1)[書式設定]>[アニメーション]を選択する。\n(2)すべてのシートをアニメーション化する場合は、[ワークブックの設定]で[オン]をクリックする。\n次に次の手順を実行する。\n・\n[期間]で、プリセットを選択するか、最大10秒のカスタム期間を指定する。\n・\n[スタイル]で、[同時]を選択してすべてのアニメーションを一度に再生するか、[シーケンシャル]\nを選択してマークをフェードアウトし、移動して並べ替えてからフェードインする。\n(3)特定のシートのブックのデフォルトを上書きするには、[選択したシート]の下の設定を変更する。\n参考：フォーマットアニメーション\nhttps://help.tableau.com/current/pro/desktop/en-us/formatting_animations.htm", "explanationImages": ["assets/image101.gif", "assets/image102.png", "assets/image103.png"]}, {"id": 115, "sourceNote": "", "prompt": "選択問題：Tableauでセットを作成する有効な方法は次のうちどれ？", "choices": [{"key": "①", "text": "データパネルでメジャーを右クリックし作成を選択>セット"}, {"key": "②", "text": "メインメニューでワークシートを表示し作成を選択>セット"}, {"key": "③", "text": "メインメニューでダッシュボードを表示し作成を選択>セット"}, {"key": "④", "text": "データパネルでディメンションを右クリックし作成を選択>セット"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nデータパネルでディメンションを右クリックし作成を選択>セット\n作成方法は問49参照\n参考：セットの作成\nhttps://help.tableau.com/current/pro/desktop/ja-jp/sortgroup_sets_create.htm", "explanationImages": []}, {"id": 116, "sourceNote": "", "prompt": "選択問題：二軸チャートを作成した後に行うべき最も重要なことは何？", "choices": [{"key": "①", "text": "ラベルの編集"}, {"key": "②", "text": "軸の同期"}, {"key": "③", "text": "色の変更"}, {"key": "④", "text": "軸を非表示"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n軸の同期\n二軸チャートを作成した後、両方が同じy軸を持っていない可能性があるため、必ずそれらの軸を同期。\n同じスケールを使用するように二軸チャートの2つの軸を揃えるには、2番目の軸を右クリックして、\n[軸の同期]を選択する。\nこれにより、2次軸のスケールが1次軸のスケールに揃えられる。", "explanationImages": ["assets/image104.png", "assets/image105.png"]}, {"id": 117, "sourceNote": "", "prompt": "選択問題：Tableauに接続すると、データセット内のデータフィールドには自動的に____と____が割り当てられる。", "choices": [{"key": "①", "text": "役割と型"}, {"key": "②", "text": "ディメンションとメジャー"}, {"key": "③", "text": "データの型と数値"}, {"key": "④", "text": "型と役割"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n役割と型\nユーザーがTableauに接続すると、データセット内のデータフィールドに役割とタイプが自動的に\n割り当てられる。\n役割には、次の2つのタイプがある。\n(1)ディメンション\n(2)メジャー\n型は次の通り。\n(1)文字列\n(2)数値\n(3)地理的役割\n(4)ブール\n(5)日付\n(6)日付と時刻", "explanationImages": []}, {"id": 118, "sourceNote": "", "prompt": "選択問題：データペインの次のアイコンは何をするために使用されるか？", "choices": [{"key": "①", "text": "データの整理"}, {"key": "②", "text": "データの並び替え"}, {"key": "③", "text": "データの表示"}, {"key": "④", "text": "データ抽出"}], "answer": ["③"], "multiple": false, "images": ["assets/image7.png"], "explanation": "③\nデータの表示\nデータの表示を使用すると、スプレッドシートのようなレイアウトでデータを検査できる。\nデータソース全体のデータを表示することも、個々のマークまたはマークのグループの基になるデータ\nを表示することもできる。\n[データの表示]ウィンドウには、デフォルトで可能な限り多くのデータが最大10000行表示される、\nフィールド名は列ヘッダーとして表示され、ドラッグアンドドロップして表示順序を変更できる。\n列ヘッダーをクリックして、その列の値を並べ替える。", "explanationImages": ["assets/image106.png"]}, {"id": 119, "sourceNote": "", "prompt": "選択問題：可能な限り少ないフィールド数でブレッド グラフを作成するための有効な方法を表すのは、次のうちどれ？", "choices": [{"key": "①", "text": "1つのメジャー"}, {"key": "②", "text": "2つのディメンション"}, {"key": "③", "text": "2つのディメンションと3つのメジャー"}, {"key": "④", "text": "2つのメジャー"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n2つのメジャー\n問13を参照", "explanationImages": []}, {"id": 120, "sourceNote": "", "prompt": "選択問題：Tableau Desktopの有効な公式データソースではないものは次のうちどれ？", "choices": [{"key": "①", "text": "Amazon Redshift"}, {"key": "②", "text": "SAP HANA"}, {"key": "③", "text": "PostgresSQL"}, {"key": "④", "text": "Google Firebase"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nGoogle Firebase\n現在、FirebaseのデータをTableauDesktopに直接接続する公式の方法はない。", "explanationImages": ["assets/image107.png"]}, {"id": 121, "sourceNote": "", "prompt": "選択問題：データブレンディングは、従来の____結合をシミュレートする。", "choices": [{"key": "①", "text": "左"}, {"key": "②", "text": "右"}, {"key": "③", "text": "外部"}, {"key": "④", "text": "内部"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n左\nデータブレンディングは従来の左結合をシミュレートする。\n2つの主な違いは、集計が実行されるとき。\n結合はデータを結合してから集計するが、ブレンドはデータを集約してから結合する。", "explanationImages": []}, {"id": 122, "sourceNote": "", "prompt": "選択問題： Tableauのメジャーのデフォルトの集計をどのように変更できるか？", "choices": [{"key": "①", "text": "メジャーを右クリック>デフォルトのプロパティ>集計"}, {"key": "②", "text": "ディメンションを右クリック>デフォルトのプロパティ>集計"}, {"key": "③", "text": "メジャーをダブルクリック>ウィンドウ>デフォルトのプロパティ"}, {"key": "④", "text": "必要に応じて随時プロパティを手動で変更"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nメジャーを右クリック>デフォルトのプロパティ>集計\n手順は以下の通り。", "explanationImages": ["assets/image108.png"]}, {"id": 123, "sourceNote": "", "prompt": "選択問題：ヒストグラムを作成するために使用できるのは次のうちどれ？", "choices": [{"key": "①", "text": "単体のメジャー"}, {"key": "②", "text": "複数のメジャー"}, {"key": "③", "text": "複数のディメンション"}, {"key": "④", "text": "単体のディメンション"}], "answer": ["①"], "multiple": false, "images": ["assets/image8.png"], "explanation": "①\n単体のメジャー\nヒストグラムは、分布の形を表示するグラフ。\n以下の通り必要なメジャーは一個。", "explanationImages": ["assets/image109.png"]}, {"id": 124, "sourceNote": "", "prompt": "選択問題： 次のアイコンはTableauで何をするか？", "choices": [{"key": "①", "text": "ストーリーの作成"}, {"key": "②", "text": "ワークシートの作成"}, {"key": "③", "text": "ダッシュボードの作成"}, {"key": "④", "text": "ストーリーとダッシュボードの作成"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nダッシュボードの作成\n左がワークブック、中央がダッシュボード、右がストーリー。", "explanationImages": ["assets/image110.png"]}, {"id": 125, "sourceNote": "", "prompt": "選択問題：____ファイルは、頻繁に使用する元のデータにすばやく接続するためのショートカット。 データソース\nファイルには、実際のデータではなく、実際のデータに接続するために必要な情報と、デフォルトプロパティの変更、\n計算フィールドの作成、グループの追加など、実際のデータに加えて行った変更が含まれている。", "choices": [{"key": "①", "text": ".twb"}, {"key": "②", "text": ".tde"}, {"key": "③", "text": ".tbm"}, {"key": "④", "text": ".tds"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n.tds\n各ファイルの特徴は、問19を参照", "explanationImages": []}, {"id": 126, "sourceNote": "", "prompt": "選択問題： デフォルトでは、データソースに接続するとTableauは何をするか？", "choices": [{"key": "①", "text": "データの抽出"}, {"key": "②", "text": "データの読み込み"}, {"key": "③", "text": "データのライブ接続"}, {"key": "④", "text": "データの並び替え"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nデータのライブ接続\nビューを作成してデータを分析する前に、まずTableauをデータに接続する必要がある。\nTableauは、さまざまな場所に保存されているさまざまなデータへの接続をサポートしている。\nデフォルトでは、データソースをTableauに接続すると、Tableauはデータへのライブ接続を作成する。", "explanationImages": []}, {"id": 127, "sourceNote": "", "prompt": "選択問題：ビジュアライゼーションにカスタムシェイプを追加したい。 これらの新しい形状をどこに追加できるか？", "choices": [{"key": "①", "text": "プログラムファイル>Tableau>Shapes"}, {"key": "②", "text": "ダウンロード>My Tableauリポジトリ>Shapes"}, {"key": "③", "text": "マイドキュメント>My Tableauリポジトリ>Shapes"}, {"key": "④", "text": "マイコンピュータ>C:>Tableau>Shapes"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nマイドキュメント>My Tableauリポジトリ>Shapes\n画像ファイルをリポジトリに追加する方法は次の通り。\n(1)インターネットで画像ファイルを検索する。\nロゴや旗などの一連の形状を使用する場合は、一貫した画像形式を見つけようとする。\n(2)画像をコンピュータにダウンロードする。\n(3)画像をマイドキュメント>マイTableauリポジトリ>シェイプフォルダにドラッグする。\n(4)Tableauを開くと、新しい図形が自動的に「図形の編集」メニューに含まれる。", "explanationImages": []}, {"id": 128, "sourceNote": "", "prompt": "正誤問題：Tableauではアニメーションがデフォルトで有効になっている。", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\n設定手順は問114参照\n※Desktop Specialist試験の最新バージョンが2022.3のため、○が正解。\n　以前までは×が正解であったので要注意(富永)", "explanationImages": []}, {"id": 129, "sourceNote": "", "prompt": "正誤問題：メジャーを不連続へ変換することは可能である", "choices": [{"key": "○", "text": "○"}, {"key": "×", "text": "×"}], "answer": ["○"], "multiple": false, "images": [], "explanation": "○\nメジャーを右クリックし不連続へ変換をクリックする。", "explanationImages": ["assets/image111.png"]}, {"id": 130, "sourceNote": "", "prompt": "複数選択問題：巨大なデータセットを使用している場合、コンテキストフィルターを使用する主な理由は次のうちどれ？", "choices": [{"key": "①", "text": "クエリーのパフォーマンスの改善"}, {"key": "②", "text": "コンテキストフィルターを一つのフィルターとするため"}, {"key": "③", "text": "データを整理するため"}, {"key": "④", "text": "抽出したいデータのみを含めるため"}], "answer": ["①", "④"], "multiple": true, "images": [], "explanation": "①\nクエリーのパフォーマンスの改善\n④\n抽出したいデータのみを含めるため\nデフォルトでは、Tableauで設定したすべてのフィルターは個別に計算される。\nつまり、各フィルターは、他のフィルターに関係なく、データソースのすべての行にアクセスする。\nただし、1つ以上のカテゴリフィルターをビューのコンテキストフィルターとして設定できる。\nコンテキストフィルターは、独立したフィルターと考えられる。\n設定したその他のフィルターは、コンテキストフィルターを通過するデータのみを処理するため、\n依存フィルターとして定義される。", "explanationImages": []}, {"id": 131, "sourceNote": "", "prompt": "選択問題： ディメンションを列シェルフにドラッグし、メジャーを行シェルフにドラッグして棒グラフを作成する。\n 積み上げ棒グラフを作成できるのは次のうちどれ？", "choices": [{"key": "①", "text": "マークカードの色に他のディメンションをドラッグ"}, {"key": "②", "text": "列シェルフに他のメジャーをドラッグ"}, {"key": "③", "text": "マークカードの色に他のメジャーをドラッグ"}, {"key": "④", "text": "行シェルフに他のディメンションをドラッグ"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nマークカードの色に他のディメンションをドラッグ\n操作イメージは以下の通り。", "explanationImages": ["assets/image112.png", "assets/image113.png"]}, {"id": 132, "sourceNote": "", "prompt": "選択問題：Excel、テキストファイルデータ、JSONファイル、.pdfファイルデータを操作する場合、____を使用して、\nフォルダー間でファイルを結合し、ワークブック間でワークシートを結合できる。 検索の範囲は、選択した接続。", "choices": [{"key": "①", "text": "ユニオン検索"}, {"key": "②", "text": "正規表現検索"}, {"key": "③", "text": "パターン検索"}, {"key": "④", "text": "ワイルドカード検索"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nワイルドカード検索\nワイルドカード検索を使用して検索条件を設定し、ユニオンにテーブルを自動的に含めることができる。\n例えば、名前に2016と含まれるシートをユニオンテーブルに含める場合、2016*と入力することで\n自動的にテーブルが結合される。", "explanationImages": ["assets/image114.png"]}, {"id": 133, "sourceNote": "", "prompt": "複数選択問題：Tableauデータソースファイル（.tds）には、次のうちどれが含まれているか？", "choices": [{"key": "①", "text": "デフォルトのフィールドプロパティ"}, {"key": "②", "text": "計算フィールド"}, {"key": "③", "text": "データソースタイプ"}, {"key": "④", "text": "ローカルデータ"}], "answer": ["①", "②", "③"], "multiple": true, "images": [], "explanation": "①\nデフォルトのフィールドプロパティ\n②\n計算フィールド\n③\nデータソースタイプ\nデータソース(.tds)\nデータソースタイプに接続するために必要な情報のみが含まれる。\n・\nデータソースタイプ\n・\nデータソースページで指定された接続情報\n例えば、データベースサーバーのアドレス、ポート、ローカルファイルの場所、テーブル\n・\nグループ、セット、計算フィールド、ビン\n・\nデフォルトのフィールドプロパティ\n例えば、数値形式、集計、並べ替え順序", "explanationImages": []}, {"id": 134, "sourceNote": "", "prompt": "選択問題：Tableauデータソース（.tds）を使用する利点は次のうちどれ？", "choices": [{"key": "①", "text": "1つ以上のワークシートに加えて、0個以上のダッシュボードとストーリーを保持する"}, {"key": "②", "text": "実際のデータではなく、実際のデータに接続するために必要な情報と、デフォルトのプロパティの変更、\n計算フィールドの作成など、実際のデータに加えて行った変更を含める"}, {"key": "③", "text": "オフラインで作業する必要があるときに、他のユーザーとデータを共有するために使用できるデータセット全体の\nサブセットのローカルコピーを作成し、パフォーマンスを向上させる"}, {"key": "④", "text": "ローカルファイルデータと背景画像をサポートするとともに、ワークブックを含む単一のZipファイルを作成する。\nこれは、元のデータにアクセスできない他のユーザーと作業を共有するのに最適"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n実際のデータではなく、実際のデータに接続するために必要な情報と、デフォルトのプロパティの変更、\n計算フィールドの作成など、実際のデータに加えて行った変更を含める\nデータソースという名前と機能が一致していない点が.tdsの特徴。\n「実際のデータではない」という点を覚えておく。\nなお、①は.twb　③は.hyperまたは.tde　④は.twbxの説明となる。", "explanationImages": []}, {"id": 135, "sourceNote": "", "prompt": "選択問題：次のグラフのうち、マークカードの[サイズ]オプションが機能しないのはどれ？", "choices": [{"key": "①", "text": "ツリーマップ"}, {"key": "②", "text": "棒グラフ"}, {"key": "③", "text": "円グラフ"}, {"key": "④", "text": "ガントチャート"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nツリーマップ\nツリーマップでは、メジャー自体がサイズと色を定義する。\n各カテゴリのメジャー合計が大きいほど、ボックスは暗くなり、大きくなる。", "explanationImages": []}, {"id": 136, "sourceNote": "", "prompt": "選択問題：次のマーカーアイコンはTableauで何をするか？", "choices": [{"key": "①", "text": "最大値のハイライト"}, {"key": "②", "text": "ハイライトのオンオフの切り替え"}, {"key": "③", "text": "色の編集"}, {"key": "④", "text": "ラベルの編集"}], "answer": ["②"], "multiple": false, "images": ["assets/image9.png"], "explanation": "②\nハイライトのオンオフの切り替え\nハイライトアイコンを選択すると、この凡例から選択した値がビューで強調表示される。\nただし、選択を解除すると、凡例で値を選択しても強調表示されない。", "explanationImages": ["assets/image115.png", "assets/image116.png"]}, {"id": 137, "sourceNote": "", "prompt": "複数選択問題：Tableauでツールヒントのコンテンツを太字にする有効な方法は次のうちどれ？", "choices": [{"key": "①", "text": "マークカードのツールヒントをクリックし太字のオプションを選択"}, {"key": "②", "text": "メニューバーのワークシートをクリックし、ツールヒントをクリックし、太字のオプションを選択"}, {"key": "③", "text": "ワークシートフォーマットの上で右クリックして書式設定をクリックし、ツールヒントを選択して太字にする"}, {"key": "④", "text": "アナリティクスをクリックし、ツールヒントオプションで太字を選択"}], "answer": ["①", "②", "③"], "multiple": true, "images": [], "explanation": "①\nマークカードのツールヒントをクリックし太字のオプションを選択\n②\nメニューバーのワークシートをクリックし、ツールヒントをクリックし、太字のオプションを選択\n③\nワークシートフォーマットの上で右クリックして書式設定をクリックし、ツールヒントを選択して太字にする\nそれぞれの方法は以下の通り。\n(1)マークカードのツールヒントをクリックし太字のオプションを選択\n(2)メニューバーのワークシートをクリックし、ツールヒントをクリックし、太字のオプションを選択\n(3)ワークシートフォーマットの上で右クリックして書式設定をクリックし、ツールヒントを選択して太字にする", "explanationImages": ["assets/image117.png", "assets/image118.png", "assets/image119.png"]}, {"id": 138, "sourceNote": "", "prompt": "選択問題：Tableauで青と緑の色は何を表しているか？", "choices": [{"key": "①", "text": "連続と不連続"}, {"key": "②", "text": "不連続と連続"}, {"key": "③", "text": "メジャーとディメンション"}, {"key": "④", "text": "ディメンションとメジャー"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n不連続と連続\n詳細はメモ", "explanationImages": []}, {"id": 139, "sourceNote": "", "prompt": "選択問題：ユニオンのフィールド名が一致しない場合、次のようになる。", "choices": [{"key": "①", "text": "両方のフィールド名はユニオンに残るが、いくつかのnull値が含まれる"}, {"key": "②", "text": "１つのフィールド名のみ正しい値としてユニオンに残るが、それはTableauが自動的にフィールド名の不一致を修正するため"}, {"key": "③", "text": "１つのフィールド名のみがnull値としてユニオンに残る"}, {"key": "④", "text": "エラーとなり、両方のフィールドはユニオンの結果から削除される"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n両方のフィールド名はユニオンに残るが、いくつかのnull値が含まれる\nデフォルトでは、両方のフィールド名がユニオンに存在するが、いくつかのnull値が含まれている。\nユニオンのフィールド名が一致しない場合、ユニオンのフィールドにはnull値が含まれる。\nマージオプションを使用して、一致しないフィールドを1つのフィールドにマージし、nullを削除できる。\nマージオプションを使用すると、元のフィールドは、一致しないフィールドの各行の最初のnull以外の値を表示する\n新しいフィールドに置き換えられる。\n・\nフィールド名が一致する場合の例\n・\nフィールド名が一致しないテーブルをマージオプションにより結合した場合の例", "explanationImages": ["assets/image120.png", "assets/image121.png", "assets/image122.png", "assets/image123.png"]}, {"id": 140, "sourceNote": "", "prompt": "複数選択問題：ライブ接続でTableau Data Extract（.tde）を使用する適当な理由は次のうちどれ？", "choices": [{"key": "①", "text": "常時、利用可能な最新のデータへアクセスできるため"}, {"key": "②", "text": "パフォーマンスを改善できるため"}, {"key": "③", "text": "Count Distinctなどの追加機能をサポートするため"}, {"key": "④", "text": "作成を高速化するため"}], "answer": ["②", "③", "④"], "multiple": true, "images": [], "explanation": "②\nパフォーマンスを改善できるため\n③\nCount Distinctなどの追加機能をサポートするため\n④\n作成を高速化するため\n抽出ファイル(.tde)\n・\n作成の高速化\n大規模なデータセットを操作している場合、抽出の作成と操作は、元のデータの操作よりも高速になる可能性あり\n・\nパフォーマンスの向上に役立つ\n抽出データソースを使用するビューを操作する場合、通常、元のデータへの接続に基づいてビューを操作する場合\nよりもパフォーマンスが向上する\n・\n追加機能のサポート\n抽出を使用すると、Count Distinct(重複排除)を計算する機能など、元のデータでは使用できない、または\nサポートされていないTableau機能を利用できる\n・\nデータへのオフラインアクセスを提供する\n抽出を使用すると、元のデータが利用できない場合に、データをローカルに保存して操作できる。\n例えば、旅行中。", "explanationImages": []}, {"id": 141, "sourceNote": "", "prompt": "複数選択問題： ディメンションについて正しいのは次のうちどれ？", "choices": [{"key": "①", "text": "ビューの詳細レベルに影響する"}, {"key": "②", "text": "数値や定量値を含む"}, {"key": "③", "text": "定性値(名前や日付、地理的データ)を含む"}, {"key": "④", "text": "リレーションデータソースの場合、日付はデフォルトでほとんどの場合ディメンションに配置される"}], "answer": ["①", "③", "④"], "multiple": true, "images": [], "explanation": "①\nビューの詳細レベルに影響する\n③\n定性値(名前や日付、地理的データ)を含む\n④\nリレーションデータソースの場合、日付はデフォルトでほとんどの場合ディメンションに配置される\nディメンションには定性的(名前、日付、地理的データなど)が含まれる。\nまた、データの分類、区分、詳細の表示に利用できる。\nディメンションは、ビューの詳細レベルに影響する。\nビューの詳細レベルというのは、例えば、住所データであれば、国、都道府県、市区町村といったデータの粒度のこと。\nなお、②のみがメジャーの説明になる。", "explanationImages": []}, {"id": 142, "sourceNote": "", "prompt": "選択問題：フィールドに負の値と正の値の両方がある場合、デフォルトの値の範囲は2つの色の範囲を使用する。\nこれは____パレットとして知られている。", "choices": [{"key": "①", "text": "発散"}, {"key": "②", "text": "反転"}, {"key": "③", "text": "収束"}, {"key": "④", "text": "ステップド"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n発散\n発散パレット\nフィールドに負の値と正の値の両方がある場合、デフォルトの値の範囲は2つの色の範囲を使用し、\nフィールドの[色の編集]ダイアログボックスには、範囲の両端に正方形のカラーボックスがあり、\nこれを、発散パレットという。\n反転\n範囲内のうろの順序を逆にするには、[反転]を選択する。\n例えば、シーケンシャルパレットで値を小さくして強度を暗くしたい場合は、パレットを逆にする。\n発散パレットの場合、カラーパレットを反転すると、各色範囲内の色合いが反転するだけでなく、\nパレット内の2つの色が入れ替わる。\nステップドカラー\n[ステップドカラー]を選択して、値を均一なビンにグループ化する。\n各ビンは色に関連付けられている。\nスピンコントロールを使用して、作成するステップ(ビン)の数を指定する。\n例えば、0～100の値の範囲の場合、値を5つのビン(0～20，20～40など)に並べ替える5つのステップで指定できる。", "explanationImages": ["assets/image124.png", "assets/image125.png", "assets/image126.png"]}, {"id": 143, "sourceNote": "", "prompt": "複数選択問題：次のうち、リファレンスラインを追加できるのはどれ？", "choices": [{"key": "①", "text": "メジャー"}, {"key": "②", "text": "ディメンション"}, {"key": "③", "text": "計算フィールド"}, {"key": "④", "text": "グループ"}], "answer": ["①", "③"], "multiple": true, "images": [], "explanation": "①\nメジャー\n③\n計算フィールド\nリファレンスライン、リファレンスバンド、分布バンド、または箱ひげ図を追加して、Tableauのビューの連続軸上の\n特定の値、領域、または範囲を識別することができる。\n例えば、複数の製品の月間売上を分析している場合、平均売上マークに参照線を含めて、各製品の平均に対する\nパフォーマンスを確認できる。\n計算フィールドは関数を用いて新しく作成するデータのことで、\n例えば、データの集約やセグメント化に使用できる。\n参考：リファレンスライン、リファレンスバンド、分布バンド、箱ひげ図\nhttps://help.tableau.com/current/pro/desktop/en-us/reference_lines.htm", "explanationImages": ["assets/image127.png"]}, {"id": 144, "sourceNote": "", "prompt": "複数選択問題：次の計算のうち、簡易表計算を必要としないものはどれ？", "choices": [{"key": "①", "text": "分散"}, {"key": "②", "text": "移動平均"}, {"key": "③", "text": "ランク"}, {"key": "④", "text": "標準偏差"}], "answer": ["①", "④"], "multiple": true, "images": [], "explanation": "①\n分散\n④\n標準偏差\n簡易表計算で使用できるメニューは以下の通り。\n移動平均は、時系列データを平滑化する手法。\n以下のイメージでは売上の各月推移を棒グラフで表しているが、緑の折れ線グラフが移動平均になる。", "explanationImages": ["assets/image128.png", "assets/image129.png"]}, {"id": 145, "sourceNote": "", "prompt": "選択問題：Tableauのビューのマークに色を追加するにはどうすればよいか？", "choices": [{"key": "①", "text": "列/行のシェルフで、フィールドを右クリックし、シェルフで編集をクリックして色を選択する"}, {"key": "②", "text": "アナリティクスペインでモデルをマークカード上の色へドラッグする"}, {"key": "③", "text": "メインメニュー上のデータをクリックし、色をクリックで選択する"}, {"key": "④", "text": "データペインでフィールドをマークカード上の色へドラッグする"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\nデータペインでフィールドをマークカード上の色へドラッグする\nビューのマークに色を割り当てるには、データペインから、フィールドをマークカードの[色]にドラッグする。\nTableauは、フィールドの値とメンバーに基づいて、マークにさまざまな色を適用する。\n例えば、カテゴリなどの個別のフィールド(青いフィールド)を[色]にドロップすると、ビュー内のマークがカテゴリ\nごとに分類され、各カテゴリに色が割り当てられる。", "explanationImages": ["assets/image130.gif"]}, {"id": 146, "sourceNote": "", "prompt": "選択問題：Tableauのストーリーポイントとはどういったもの？", "choices": [{"key": "①", "text": "ひとつのワークシートまたはダッシュボード"}, {"key": "②", "text": "ダッシュボードの集まり"}, {"key": "③", "text": "ワークシートとダッシュボードの集まり"}, {"key": "④", "text": "ワークシートの集まり"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nひとつのワークシートまたはダッシュボード\nストーリーは情報を伝達するために連携して機能する一連の視覚化。\nストーリーを作成して、データの説明を伝えたり、コンテキストを提供したり、決定が結果にどのように関連している\nかを示したり、単に説得力のある主張をしたりすることができる。\nストーリーはシートであるため、ワークシートとダッシュボードの作成、名前付け、及び管理に使用する方法は、\nストーリーにも適用される。\n同時に、ストーリーはシートのコレクションでもあり、順番に並べられている。\nストーリー内の個々のシート(ワークシートまたはダッシュボード)は、ストーリーポイントと呼ばれる。", "explanationImages": ["assets/image21.png"]}, {"id": 147, "sourceNote": "", "prompt": "選択問題：ビューの棒グラフのラベルでグループ化をすると、次のうちどれが発生するか？", "choices": [{"key": "①", "text": "ラベルでのグループ化はできない"}, {"key": "②", "text": "ビューでは何も変化しないが、ディメンションにグループが作られる"}, {"key": "③", "text": "選択された数値の色が同じになり、残りの数値は異なった色になる"}, {"key": "④", "text": "新しいマーク(バー)が作られ、グループの中にすべて統合される"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n新しいマーク(バー)が作られ、グループの中にすべて統合される\nビューでラベルを選択してからグループ化する。\nグループ化された新しいバーが作成され、バーの色は同じままになる。", "explanationImages": ["assets/image131.png", "assets/image132.png"]}, {"id": 148, "sourceNote": "", "prompt": "選択問題：ダッシュボードでフィルターを表示している場合、どのように再配置できるか？", "choices": [{"key": "①", "text": "フィルタ内の任意の場所をクリックしてドラッグする"}, {"key": "②", "text": "上の2本の線をクリックしてフィルターをドラッグする"}, {"key": "③", "text": "ドロップダウンをクリックしてフィルターをドラッグする"}, {"key": "④", "text": "フィルタータイトルをクリックし、ドラッグする"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\n上の２本の線をクリックしてフィルターをドラッグする", "explanationImages": ["assets/image133.png"]}, {"id": 149, "sourceNote": "", "prompt": "選択問題：青いフィールドが表示されている場合は、通常、ビューに____が追加される。", "choices": [{"key": "①", "text": "何も追加されない"}, {"key": "②", "text": "ヘッダー"}, {"key": "③", "text": "軸"}, {"key": "④", "text": "ヘッダーと軸"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nヘッダー\n青いフィールド(不連続)の場合はヘッダーが追加される。\n緑のフィールド(連続)は軸が追加される。", "explanationImages": ["assets/image134.png", "assets/image135.png"]}, {"id": 150, "sourceNote": "", "prompt": "選択問題：次のうちどれがディメンションか？", "choices": [{"key": "①", "text": "メジャーネーム"}, {"key": "②", "text": "レコード数"}, {"key": "③", "text": "経度"}, {"key": "④", "text": "緯度"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\nメジャーネーム\n他3つはすべてメジャー値。", "explanationImages": ["assets/image136.png"]}, {"id": 151, "sourceNote": "", "prompt": "選択問題： バージョン10.5以降、新しい抽出を作成すると、.tde形式ではなく____形式が使用される。", "choices": [{"key": "①", "text": ".hyper"}, {"key": "②", "text": ".twbx"}, {"key": "③", "text": ".tdex"}, {"key": "④", "text": ".tds"}], "answer": ["①"], "multiple": false, "images": [], "explanation": "①\n.hyper\nバージョン10.5以降、新しい抽出を作成すると、.tde形式ではなく.hyper形式が使用される。\n.hyper形式の抽出は、改善されたデータエンジンを利用する。\nこれは、以前のデータエンジンと同じ高速な分析およびクエリのパフォーマンスをサポートするが、\nさらに大きな抽出に対応する。", "explanationImages": []}, {"id": 152, "sourceNote": "", "prompt": "複数選択問題： 他に影響を与えずに行または列のいずれかを太字にする有効な方法は次のうちどれ？", "choices": [{"key": "①", "text": "メニューバーの書式設定>フォント>ヘッダーオプションの文字を選択"}, {"key": "②", "text": "行と列を右クリック>書式設定>フォントオプションの太字をクリック"}, {"key": "③", "text": "書式設定>メニューバーのフォント>ヘッダーオプションの太字を選択"}, {"key": "④", "text": "マークカードのテキストラベルを選択>行と列>太字を選択"}], "answer": ["①", "②"], "multiple": true, "images": [], "explanation": "①\nメニューバーの書式設定>フォント>ヘッダーオプションの文字を選択\n②\n行と列を右クリック>書式設定>フォントオプションの太字をクリック\n(①メニューバーの書式設定>フォント>ヘッダーオプションの文字を選択の例)\n(②行と列を右クリック>書式設定>フォントオプションの太字をクリックの例)", "explanationImages": ["assets/image137.png", "assets/image138.png", "assets/image139.png"]}, {"id": 153, "sourceNote": "", "prompt": "選択問題：Tableauで軸を太字としてフォーマットするにはどうすればよいか？", "choices": [{"key": "①", "text": "軸を右クリック>軸の編集>太字にする"}, {"key": "②", "text": "軸を選択>キーボードでControl+Bを入力"}, {"key": "③", "text": "軸を右クリック>書式設定>太字にする"}, {"key": "④", "text": "メインメニューバーの書式設定>行ラベルを選択>太字にする"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\n軸を右クリック>書式設定>太字にする\n操作イメージは以下の通り。", "explanationImages": ["assets/image140.png", "assets/image141.png"]}, {"id": 154, "sourceNote": "", "prompt": "選択問題：次のイメージで新しいメジャーを行シェルフと列シェルフにドラッグした場合、マークの総数はいくつになるか？", "choices": [{"key": "①", "text": "行にドラッグすると14マーク、列にドラッグすると7マーク"}, {"key": "②", "text": "行にドラッグすると14マーク、列にドラッグすると14マーク"}, {"key": "③", "text": "行にドラッグすると7マーク、列にドラッグすると7マーク"}, {"key": "④", "text": "行にドラッグすると7マーク、列にドラッグすると14マーク"}], "answer": ["①"], "multiple": false, "images": ["assets/image10.png"], "explanation": "①\n行にドラッグすると14マーク、列にドラッグすると7マーク\n新しいメジャーを行シェルフにドラッグすると、次のようになる。\n7列が２行で合計14マークになる。\nただし、同じメジャーを列シェルフにドラッグすると、1つの行と各列に対して作成されたグラフが表示され7マークに\nなる。", "explanationImages": ["assets/image142.png", "assets/image143.png"]}, {"id": 155, "sourceNote": "", "prompt": "選択問題：Tableauで視覚化するための軸はいつ作成されるか？", "choices": [{"key": "①", "text": "行・列に不連続フィールドをドラッグしたとき"}, {"key": "②", "text": "行・列にメジャーをドラッグしたとき"}, {"key": "③", "text": "行・列にディメンションをドラッグしたとき"}, {"key": "④", "text": "行・列に連続フィールドをドラッグしたとき"}], "answer": ["④"], "multiple": false, "images": [], "explanation": "④\n行・列に連続フィールドをドラッグしたとき\nTableauの個々の軸は、行または列に連続フィールドを追加することによって表示される。", "explanationImages": []}, {"id": 156, "sourceNote": "", "prompt": "選択問題：複数の視覚化を含むダッシュボードを画像としてエクスポートする有効な方法は次のうちどれ？", "choices": [{"key": "①", "text": "メニューバーのワークシートをクリックしてから、エクスポートで画像を選択する"}, {"key": "②", "text": "メニューバーのダッシュボードをクリックしてから、画像をコピーする"}, {"key": "③", "text": "ダッシュボードを右クリックしてから、画像をコピーする"}, {"key": "④", "text": "ダッシュボードの浮動エクスポートワークシートオプションを使用する"}], "answer": ["②"], "multiple": false, "images": [], "explanation": "②\nメニューバーのダッシュボードをクリックしてから、画像をコピーする\n操作イメージは以下の通り。\nなお、①と③の場合はダッシュボード全体ではなくワークシートの1つだけがコピーされる。\n④については存在しないオプション。", "explanationImages": ["assets/image144.png"]}, {"id": 157, "sourceNote": "", "prompt": "選択問題：TableauのシートをPDFにエクスポートする理由は次のうちどれ？", "choices": [{"key": "①", "text": "ビジュアライゼーションでフィルターを使用する場合"}, {"key": "②", "text": "ビジュアライゼーションにパラメータを動的に入力する場合"}, {"key": "③", "text": "ビジュアライゼーションの静的ビューが必要な場合"}, {"key": "④", "text": "ビジュアライゼーションを見たい場合"}], "answer": ["③"], "multiple": false, "images": [], "explanation": "③\nビジュアライゼーションの静的ビューが必要な場合\nビジュアライゼーションをエクスポートすると、ビジュアライゼーションの静的ビューが得られる。\nそれを操作したり、フィルターを使用したり、ビジュアライゼーションにエクスポートされたPDFに動的に何かを\n入力したりすることはできない。\nTableau Desktopでは、ビューをハードコピーとして印刷するのではなく、PDFファイルとして保存できる。\nコンピューターにAdobeAcrobatをインストールする必要はない。\n個々のシートをPDFに印刷する場合、ビューのフィルターは含まれない。\nフィルタを表示するには、シートを含むダッシュボードを作成し、ダッシュボードをPDFにエクスポートする。", "explanationImages": []}], "notes": [{"title": "メモ", "lines": [{"row": 1, "text": "・ ディメンション"}, {"row": 2, "text": "定性的値(名前、日付、地理的データなど)が含まれる。"}, {"row": 3, "text": "データの分類、区分、詳細の表示に利用できる。"}, {"row": 4, "text": "ビューの詳細レベルに影響する。"}, {"row": 5, "text": "・ メジャー"}, {"row": 6, "text": "測定可能な数値と定量的な値が含まれる。"}, {"row": 7, "text": "集計できる。"}, {"row": 8, "text": "ビューにドラックすると、Tableauはそのメジャーに(既定で)集計を適用する"}, {"row": 9, "text": "・ 青と緑のフィールド"}, {"row": 10, "text": "Tableauは、フィールドが不連続(青)か連続(緑)かによって、"}, {"row": 11, "text": "ビューでのデータ表示方法が異なる。"}, {"row": 12, "text": "連続と不連続は数学用語で以下の意味。"}, {"row": 13, "text": "連続：中断されることなく、つながった全体を形成する"}, {"row": 14, "text": "不連続：それぞれが別々かつ個別であること"}, {"row": 15, "text": "・ ブール値"}, {"row": 16, "text": "例えば国内・国外のように2種類のデータで区分される場合に適用するデータ型で、"}, {"row": 17, "text": "文字列などよりも計算が速くなる。"}, {"row": 18, "text": "・ ハイライトアクション"}, {"row": 19, "text": "特定のマークに色を付け、他のすべてのマークを薄く表示して、興味のあるマークに"}, {"row": 20, "text": "注意を喚起することができる。"}, {"row": 21, "text": "さまざまなツールを使用してビュー内のマークをハイライトできる。"}, {"row": 22, "text": "たとえば、ハイライトするマークを手動で、選択、色の凡例を使用して関連する"}, {"row": 23, "text": "マークを選択、ハイライターを使用してコンテキスト内のマークを検索、"}, {"row": 24, "text": "または詳細なハイライトアクションを作成することができる。"}, {"row": 25, "text": "・ ワークブック(.twb)"}, {"row": 26, "text": "シート、ダッシュボード、ストーリーお情報を持つ。"}, {"row": 27, "text": "それ以外に、データの列の別名や、計算フィールドの情報もワークブックが持つ。"}, {"row": 28, "text": "データそのものは含まない純粋なレポート部分のみを保存する。"}, {"row": 29, "text": "・ 内部結合"}, {"row": 30, "text": "両方のテーブルに一致がある値を含む表。"}, {"row": 31, "text": "・ 外部結合"}, {"row": 32, "text": "両方のテーブルのすべての値を含む表。"}, {"row": 33, "text": "いずれかの表と一致しない場合、データグリッドにNULL値が表示される。"}, {"row": 34, "text": "・ ユニオン"}, {"row": 35, "text": "結合の一種ではない。"}, {"row": 36, "text": "1つの表の行にあるデータを別の表に追加することによって2つ以上の表を組み合わせる"}, {"row": 37, "text": "別の方法。"}, {"row": 38, "text": "ユニオンを実行する2つの表のフィールド数が同じで、"}, {"row": 39, "text": "両方のフィールドで名前とデータ型が一致していることが理想。"}, {"row": 40, "text": "・ ポイント"}, {"row": 41, "text": "アクションを実行するビュー内のマークにポインターをあわせる。"}, {"row": 42, "text": "このオプションは、ダッシュボード内のハイライト アクションとフィルター アクション"}, {"row": 43, "text": "に対して有効に機能する。"}, {"row": 48, "text": "・ 選択"}, {"row": 49, "text": "アクションを実行するビュー内のマークをクリックする。"}, {"row": 50, "text": "このオプションは、すべてのタイプのアクションに対して有効に機能する。"}, {"row": 55, "text": "・ メニュー"}, {"row": 56, "text": "Tableau Desktopで、ビュー内の選択したマークを右クリック(MacではControlを"}, {"row": 57, "text": "押しながらクリック)して、コンテキスト メニューのオプションを選択する。"}], "images": [{"row": 44, "src": "assets/image145.png"}, {"row": 51, "src": "assets/image146.png"}, {"row": 58, "src": "assets/image147.png"}]}, {"title": "グラフ特徴", "lines": [{"row": 1, "text": "・ グラフ"}, {"row": 2, "text": "① ガントチャート"}, {"row": 3, "text": "たとえば、さまざまな製品の平均配達時間を表示する一定期間におけるイベントやアクティビティを"}, {"row": 4, "text": "表示する場合など、一定期間におけるイベントやアクティビティを表示するには、ガントチャートを使用する"}, {"row": 19, "text": "② ブレットグラフ"}, {"row": 20, "text": "あるデータを棒グラフの形で展開し、そこに比較したい基準データ(目標値など)を線の形でプロットしたもの。"}, {"row": 21, "text": "少ないスペースで、2つのデータを比較することが可能。"}, {"row": 34, "text": "③ ヒストグラム"}, {"row": 35, "text": "分布の形を表示するグラフ。"}, {"row": 36, "text": "ヒストグラムは棒グラフのように見えるが、連続メジャーの値を範囲またはビンにグルーピング化する。"}, {"row": 37, "text": "(ビン：サンプルデータをグラフ用に並び替えるために使用する、等間隔の区間のこと)"}, {"row": 38, "text": "例：出荷までの日数をヒストグラム表示した場合"}, {"row": 55, "text": "→出荷までの日数が4日(左から4番目の棒グラフ)かかる集団が最も多いとわかる"}, {"row": 56, "text": "④ ツリーマップ"}, {"row": 57, "text": "ネストされた長方形にデータを表示する。"}, {"row": 58, "text": "ディメンションを使用してツリーマップの構造を定義し、"}, {"row": 59, "text": "メジャーを使用して個々の長方形のサイズまたは色を定義する。"}, {"row": 60, "text": "比較的単純なデータ可視化で、視覚的に魅力的な形式。"}], "images": [{"row": 4, "src": "assets/image148.png"}, {"row": 22, "src": "assets/image17.png"}, {"row": 39, "src": "assets/image149.png"}, {"row": 61, "src": "assets/image150.png"}]}]};
